struct ConeCommand;

impl Command for ConeCommand {
    fn name(&self) -> &'static str {
        "Cone"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let options = parse_axial_primitive_options(arguments, CONE_USAGE, false)?;
        let tolerance = document.tolerance();
        let (base_frame, radius) =
            axial_primitive_frame(options.center, options.radius, options.axis, tolerance)?;
        if options.solid {
            let brep = Brep::try_cone(base_frame, radius, options.height, tolerance)?;
            let id = document.add_geometry(Geometry::Brep(brep))?;
            Ok(format!(
                "Added closed B-rep cone {id} (radius {radius:.6}, height {:.6})",
                options.height
            ))
        } else {
            let apex = options
                .center
                .translated(base_frame.z_axis().as_vector().scaled(options.height)?)?;
            let apex_frame = Frame3::try_from_directions(
                apex,
                base_frame.x_axis().as_vector(),
                base_frame.y_axis().as_vector(),
                tolerance,
            )?;
            let surface = NurbsSurface::try_cone(apex_frame, radius, -options.height)?;
            let id = document.add_geometry(Geometry::NurbsSurface(surface))?;
            Ok(format!(
                "Added open NURBS cone {id} (radius {radius:.6}, height {:.6})",
                options.height
            ))
        }
    }
}

struct ConicCommand;

impl Command for ConicCommand {
    fn name(&self) -> &'static str {
        "Conic"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let options = parse_conic_options(arguments)?;
        let tolerance = document.tolerance();
        let curve = match options.definition {
            ConicDefinition::Rho(rho) => {
                NurbsCurve::try_conic(options.start, options.apex, options.end, rho)?
            }
            ConicDefinition::ThroughPoint(through) => NurbsCurve::try_conic_through_point(
                options.start,
                options.apex,
                options.end,
                through,
                tolerance,
            )?,
        };
        let middle_weight = curve.control_points()[1].weight();
        let id = document.add_geometry(Geometry::NurbsCurve(curve))?;
        Ok(format!(
            "Added exact NURBS conic {id} (middle weight {middle_weight:.6})"
        ))
    }
}

fn parabolic_frame_and_dimensions(
    positionals: ParabolicPositionals,
    tolerance: Tolerance,
) -> Result<(Frame3, Real, Real, Point3, Real), CommandError> {
    let (vertex, focus, axis, focal_distance, end_offset) = match positionals.construction {
        ParabolicConstruction::Focus => {
            let focus = positionals.first;
            let axis = focus.vector_to(positionals.second)?.normalized(tolerance)?;
            let focus_to_end = focus.vector_to(positionals.end)?;
            let axial_coordinate = focus_to_end.dot(axis.as_vector())?;
            let axial = axis.as_vector().scaled(axial_coordinate)?;
            let radial = Vector3::try_new(
                focus_to_end.x() - axial.x(),
                focus_to_end.y() - axial.y(),
                focus_to_end.z() - axial.z(),
            )?;
            let radius = radial.length()?;
            let half_sum = 0.5 * axial_coordinate.hypot(radius) + 0.5 * axial_coordinate.abs();
            let (focal_distance, height) = if axial_coordinate >= 0.0 {
                (0.25 * radius * (radius / half_sum), half_sum)
            } else {
                (half_sum, 0.25 * radius * (radius / half_sum))
            };
            let vertex = focus.translated(axis.as_vector().scaled(-focal_distance)?)?;
            return Ok((
                Frame3::try_from_x_and_normal(vertex, radial, axis.as_vector(), tolerance)?,
                radius,
                height,
                focus,
                focal_distance,
            ));
        }
        ParabolicConstruction::Vertex => {
            let vertex = positionals.first;
            let vertex_to_focus = vertex.vector_to(positionals.second)?;
            let axis = vertex_to_focus.normalized(tolerance)?;
            let focal_distance = vertex_to_focus.length()?;
            (
                vertex,
                positionals.second,
                axis,
                focal_distance,
                vertex.vector_to(positionals.end)?,
            )
        }
    };

    let axial_coordinate = end_offset.dot(axis.as_vector())?;
    let axial = axis.as_vector().scaled(axial_coordinate)?;
    let radial = Vector3::try_new(
        end_offset.x() - axial.x(),
        end_offset.y() - axial.y(),
        end_offset.z() - axial.z(),
    )?;
    let radius = radial.length()?;
    let height = 0.25 * radius * (radius / focal_distance);
    Ok((
        Frame3::try_from_x_and_normal(vertex, radial, axis.as_vector(), tolerance)?,
        radius,
        height,
        focus,
        focal_distance,
    ))
}

struct ParabolaCommand;

impl Command for ParabolaCommand {
    fn name(&self) -> &'static str {
        "Parabola"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let options = parse_parabola_options(arguments)?;
        let (frame, radius, height, focus, focal_distance) =
            parabolic_frame_and_dimensions(options.positionals, document.tolerance())?;
        let parabola = NurbsCurve::try_parabola(frame, radius, height, options.half)?;
        let focus_id = if options.mark_focus {
            Some(document.add_geometry(Geometry::Point(focus))?)
        } else {
            None
        };
        let id = document.add_geometry(Geometry::NurbsCurve(parabola))?;
        let focus_suffix = focus_id
            .map(|focus_id| format!(" and focus point {focus_id}"))
            .unwrap_or_default();
        Ok(format!(
            "Added {} NURBS parabola {id}{focus_suffix} (radius {radius:.6}, height {height:.6}, focus distance {focal_distance:.6})",
            if options.half { "half" } else { "full" },
        ))
    }
}

struct ParabolaThreePointCommand;

impl Command for ParabolaThreePointCommand {
    fn name(&self) -> &'static str {
        "Parabola3Pt"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let options = parse_parabola_three_point_options(arguments)?;
        let tolerance = document.tolerance();
        let curve = match options.mode {
            ParabolaThreePointMode::Focus => NurbsCurve::try_parabola_from_focus(
                options.special,
                options.start,
                options.end,
                tolerance,
            )?,
            ParabolaThreePointMode::ThroughPoint => {
                let direction_point = options
                    .direction_point
                    .expect("through-point options include a direction point");
                NurbsCurve::try_parabola_through_point(
                    options.start,
                    options.special,
                    options.end,
                    options.special.vector_to(direction_point)?,
                    tolerance,
                )?
            }
            ParabolaThreePointMode::Vertex => NurbsCurve::try_parabola_from_vertex(
                options.special,
                options.start,
                options.end,
                tolerance,
            )?,
        };
        let focus = curve.try_parabola_focus(tolerance)?;
        let focus_id = if options.mark_focus {
            Some(document.add_geometry(Geometry::Point(focus))?)
        } else {
            None
        };
        let id = document.add_geometry(Geometry::NurbsCurve(curve))?;
        let focus_suffix = focus_id
            .map(|focus_id| format!(" and focus point {focus_id}"))
            .unwrap_or_default();
        Ok(format!(
            "Added three-point NURBS parabola {id}{focus_suffix} (focus {})",
            format_point(focus)
        ))
    }
}

struct ParaboloidCommand;

impl Command for ParaboloidCommand {
    fn name(&self) -> &'static str {
        "Paraboloid"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let options = parse_paraboloid_options(arguments)?;
        let (frame, radius, height, focus, focal_distance) =
            parabolic_frame_and_dimensions(options.positionals, document.tolerance())?;
        let paraboloid =
            Brep::try_paraboloid(frame, radius, height, options.solid, document.tolerance())?;
        let focus_id = if options.mark_focus {
            Some(document.add_geometry(Geometry::Point(focus))?)
        } else {
            None
        };
        let id = document.add_geometry(Geometry::Brep(paraboloid))?;
        let focus_suffix = focus_id
            .map(|focus_id| format!(" and focus point {focus_id}"))
            .unwrap_or_default();
        Ok(format!(
            "Added {} B-rep paraboloid {id}{focus_suffix} (radius {radius:.6}, height {height:.6}, focus distance {focal_distance:.6})",
            if options.solid { "closed" } else { "open" },
        ))
    }
}

fn hyperbola_radial_component(
    offset: Vector3,
    axis: Vector3,
    axial: Real,
) -> Result<Vector3, GeometryError> {
    Vector3::try_new(
        (-axial).mul_add(axis.x(), offset.x()),
        (-axial).mul_add(axis.y(), offset.y()),
        (-axial).mul_add(axis.z(), offset.z()),
    )
}

fn centered_hyperbola_definition(
    center: Point3,
    axis: Vector3,
    focal_distance: Real,
    end: Point3,
    foci: [Point3; 2],
    tolerance: Tolerance,
) -> Result<HyperbolaDefinition, CommandError> {
    let offset = center.vector_to(end)?;
    let axial_extent = offset.dot(axis)?;
    let radial_direction = hyperbola_radial_component(offset, axis, axial_extent)?;
    let radial_extent = radial_direction.length()?;
    if axial_extent <= tolerance.absolute() || radial_extent <= tolerance.absolute() {
        return Err(GeometryError::Degenerate {
            context: "hyperbola",
        }
        .into());
    }

    // The difference in distances to the two foci is 2a. Evaluate that
    // difference through its conjugate expression to retain accuracy for
    // endpoints far from the center.
    let scale = focal_distance.max(axial_extent).max(radial_extent);
    let normalized_focus = focal_distance / scale;
    let normalized_axial = axial_extent / scale;
    let normalized_radial = radial_extent / scale;
    let distance_to_negative = (normalized_axial + normalized_focus).hypot(normalized_radial);
    let distance_to_positive = (normalized_axial - normalized_focus).hypot(normalized_radial);
    let semi_transverse_axis = scale
        * ((2.0 * normalized_focus * normalized_axial)
            / (distance_to_negative + distance_to_positive));
    if !semi_transverse_axis.is_finite()
        || semi_transverse_axis <= 0.0
        || semi_transverse_axis >= focal_distance
    {
        return Err(GeometryError::Degenerate {
            context: "hyperbola",
        }
        .into());
    }
    let semi_conjugate_axis = (focal_distance - semi_transverse_axis).sqrt()
        * (focal_distance + semi_transverse_axis).sqrt();
    if !semi_conjugate_axis.is_finite() || semi_conjugate_axis <= 0.0 {
        return Err(GeometryError::Degenerate {
            context: "hyperbola",
        }
        .into());
    }

    Ok(HyperbolaDefinition {
        center,
        axis,
        radial_direction,
        semi_transverse_axis,
        semi_conjugate_axis,
        axial_extent,
        foci,
    })
}

fn hyperbola_definition(
    options: HyperbolaCommandOptions,
    tolerance: Tolerance,
) -> Result<HyperbolaDefinition, CommandError> {
    match options.positionals.construction {
        HyperbolaConstruction::Center => {
            let center = options.positionals.first;
            let to_focus = center.vector_to(options.positionals.second)?;
            let focal_distance = to_focus.length()?;
            let axis = to_focus.normalized(tolerance)?.as_vector();
            let opposite_focus = center.translated(axis.scaled(-focal_distance)?)?;
            centered_hyperbola_definition(
                center,
                axis,
                focal_distance,
                options.positionals.end,
                [opposite_focus, options.positionals.second],
                tolerance,
            )
        }
        HyperbolaConstruction::Foci => {
            let first_focus = options.positionals.first;
            let second_focus = options.positionals.second;
            let between_foci = first_focus.vector_to(second_focus)?;
            let focal_distance = 0.5 * between_foci.length()?;
            let axis = between_foci.normalized(tolerance)?.as_vector();
            let center = Point3::try_new(
                0.5 * first_focus.x() + 0.5 * second_focus.x(),
                0.5 * first_focus.y() + 0.5 * second_focus.y(),
                0.5 * first_focus.z() + 0.5 * second_focus.z(),
            )?;
            centered_hyperbola_definition(
                center,
                axis,
                focal_distance,
                options.positionals.end,
                [first_focus, second_focus],
                tolerance,
            )
        }
        HyperbolaConstruction::Vertex => {
            let vertex = options.positionals.first;
            let focus = options.positionals.second;
            let vertex_to_focus = vertex.vector_to(focus)?;
            let vertex_focus_distance = vertex_to_focus.length()?;
            let axis = vertex_to_focus.normalized(tolerance)?.as_vector();
            let offset = vertex.vector_to(options.positionals.end)?;
            let beyond_vertex = offset.dot(axis)?;
            let radial_direction = hyperbola_radial_component(offset, axis, beyond_vertex)?;
            let radial_extent = radial_direction.length()?;
            if beyond_vertex <= tolerance.absolute() || radial_extent <= tolerance.absolute() {
                return Err(GeometryError::Degenerate {
                    context: "hyperbola",
                }
                .into());
            }

            let scale = vertex_focus_distance.max(beyond_vertex).max(radial_extent);
            let normalized_focus = vertex_focus_distance / scale;
            let normalized_beyond = beyond_vertex / scale;
            let normalized_radial = radial_extent / scale;
            let denominator =
                normalized_radial * normalized_radial - 4.0 * normalized_beyond * normalized_focus;
            let endpoint_to_focus = (normalized_beyond - normalized_focus).hypot(normalized_radial);
            let numerator = normalized_beyond
                * normalized_focus
                * (endpoint_to_focus + normalized_beyond + normalized_focus);
            if denominator <= 0.0 || numerator <= 0.0 {
                return Err(GeometryError::Degenerate {
                    context: "hyperbola",
                }
                .into());
            }
            let semi_transverse_axis = scale * (numerator / denominator);
            let focal_distance = semi_transverse_axis + vertex_focus_distance;
            let semi_conjugate_axis = vertex_focus_distance.sqrt()
                * (2.0 * semi_transverse_axis + vertex_focus_distance).sqrt();
            let axial_extent = semi_transverse_axis + beyond_vertex;
            if ![
                semi_transverse_axis,
                focal_distance,
                semi_conjugate_axis,
                axial_extent,
            ]
            .into_iter()
            .all(|value| value.is_finite() && value > 0.0)
            {
                return Err(GeometryError::Degenerate {
                    context: "hyperbola",
                }
                .into());
            }
            let center = vertex.translated(axis.scaled(-semi_transverse_axis)?)?;
            let opposite_focus = center.translated(axis.scaled(-focal_distance)?)?;
            Ok(HyperbolaDefinition {
                center,
                axis,
                radial_direction,
                semi_transverse_axis,
                semi_conjugate_axis,
                axial_extent,
                foci: [opposite_focus, focus],
            })
        }
        HyperbolaConstruction::Coefficient => {
            let center = options.positionals.first;
            let axis = center
                .vector_to(options.positionals.second)?
                .normalized(tolerance)?
                .as_vector();
            let offset = center.vector_to(options.positionals.end)?;
            let axial_extent = offset.dot(axis)?;
            let picked_radial = hyperbola_radial_component(offset, axis, axial_extent)?;
            if axial_extent <= options.semi_transverse_axis
                || picked_radial.length()? <= tolerance.absolute()
            {
                return Err(GeometryError::Degenerate {
                    context: "hyperbola",
                }
                .into());
            }
            let radial_direction = picked_radial.scaled(-1.0)?;
            let focal_distance = options
                .semi_transverse_axis
                .hypot(options.semi_conjugate_axis);
            let negative_focus = center.translated(axis.scaled(-focal_distance)?)?;
            let positive_focus = center.translated(axis.scaled(focal_distance)?)?;
            Ok(HyperbolaDefinition {
                center,
                axis,
                radial_direction,
                semi_transverse_axis: options.semi_transverse_axis,
                semi_conjugate_axis: options.semi_conjugate_axis,
                axial_extent,
                foci: [negative_focus, positive_focus],
            })
        }
    }
}

fn hyperbola_branch(
    definition: HyperbolaDefinition,
    branch_sign: Real,
    tolerance: Tolerance,
) -> Result<NurbsCurve, GeometryError> {
    let frame = Frame3::try_from_directions(
        definition.center,
        definition.axis.scaled(branch_sign)?,
        definition.radial_direction,
        tolerance,
    )?;
    NurbsCurve::try_hyperbola(
        frame,
        definition.semi_transverse_axis,
        definition.semi_conjugate_axis,
        definition.axial_extent,
    )
}

struct HyperbolaCommand;

impl Command for HyperbolaCommand {
    fn name(&self) -> &'static str {
        "Hyperbola"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let options = parse_hyperbola_options(arguments)?;
        let tolerance = document.tolerance();
        let definition = hyperbola_definition(options, tolerance)?;
        let branch_signs: &[Real] = if options.both_branches {
            &[-1.0, 1.0]
        } else {
            &[1.0]
        };
        let curves = branch_signs
            .iter()
            .map(|sign| hyperbola_branch(definition, *sign, tolerance))
            .collect::<Result<Vec<_>, _>>()?;

        let mut focus_ids = Vec::new();
        if options.mark_foci {
            for sign in branch_signs {
                let focus = definition.foci[usize::from(*sign > 0.0)];
                focus_ids.push(document.add_geometry(Geometry::Point(focus))?);
            }
        }
        let mut curve_ids = Vec::with_capacity(curves.len());
        for curve in curves {
            curve_ids.push(document.add_geometry(Geometry::NurbsCurve(curve))?);
        }
        Ok(format!(
            "Added {} hyperbola branch{} ({curve_ids:?}){}{}",
            curve_ids.len(),
            if curve_ids.len() == 1 { "" } else { "es" },
            if focus_ids.is_empty() {
                String::new()
            } else {
                format!(" and {} focus point(s) {focus_ids:?}", focus_ids.len())
            },
            if options.show_asymptotes {
                "; asymptotes are preview-only"
            } else {
                ""
            }
        ))
    }
}

struct HelixCommand;

impl Command for HelixCommand {
    fn name(&self) -> &'static str {
        "Helix"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let options = parse_helix_options(arguments)?;
        let tolerance = document.tolerance();
        let axis = options.axis_start.vector_to(options.axis_end)?;
        let height = axis.length()?;
        let (frame, radius) =
            axial_primitive_frame(options.axis_start, options.radius, axis, tolerance)?;
        let turn_count = match options.advance {
            SpiralAdvance::Turns(turn_count) => turn_count,
            SpiralAdvance::Pitch(pitch) => height / pitch,
        };
        let signed_turn_count = if options.reverse_twist {
            -turn_count
        } else {
            turn_count
        };
        let curve = NurbsCurve::try_helix(frame, radius, height, signed_turn_count)?;
        let id = document.add_geometry(Geometry::NurbsCurve(curve))?;
        Ok(format!(
            "Added NURBS helix {id} (radius {radius:.6}, height {height:.6}, turns {turn_count:.6}{})",
            if options.reverse_twist {
                ", reverse twist"
            } else {
                ""
            }
        ))
    }
}

struct SpiralCommand;

impl Command for SpiralCommand {
    fn name(&self) -> &'static str {
        "Spiral"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let options = parse_spiral_options(arguments)?;
        let tolerance = document.tolerance();
        if let SpiralAxis::AroundCurve {
            path_name,
            points_per_turn,
        } = &options.axis
        {
            let (path_geometry, path_id) = spiral_curve_path(document, path_name.as_deref())?;
            let rail = geometry_curve_ref(&path_geometry)
                .expect("spiral path resolution validates the rail geometry");
            let endpoint_samples = rail.divide_by_count_samples(1, true, tolerance)?;
            let radius_point = match options.radii[0] {
                AxialPrimitiveRadius::Point(point) => point,
                AxialPrimitiveRadius::Numeric(_) => {
                    return Err(CommandError::Usage(SPIRAL_USAGE));
                }
            };
            let start_radius = curve_radius_value(endpoint_samples[0], options.radii[0])?;
            let end_radius = curve_radius_value(endpoint_samples[1], options.radii[1])?;
            if start_radius <= 0.0 || end_radius < 0.0 {
                return Err(GeometryError::InvalidSpiralDimensions.into());
            }
            let rail_length = rail.length(tolerance)?;
            let turn_count = match options.advance {
                SpiralAdvance::Turns(turn_count) => turn_count,
                SpiralAdvance::Pitch(pitch) => rail_length / pitch,
            };
            let signed_turn_count = if options.reverse_twist {
                -turn_count
            } else {
                turn_count
            };
            let curve = NurbsCurve::try_swept_spiral(
                rail,
                radius_point,
                signed_turn_count,
                [start_radius, end_radius],
                *points_per_turn,
                tolerance,
            )?;
            let id = document.add_geometry(Geometry::NurbsCurve(curve))?;
            return Ok(format!(
                "Added NURBS spiral {id} around curve {path_id} (radii {start_radius:.6} to {end_radius:.6}, turns {turn_count:.6}, {points_per_turn} points per turn{})",
                if options.reverse_twist {
                    ", reverse twist"
                } else {
                    ""
                }
            ));
        }
        let (axis_start, axis_end, axis, height) = match options.axis {
            SpiralAxis::Segment { start, end } => {
                let axis = start.vector_to(end)?;
                let height = axis.length()?;
                (start, end, axis, height)
            }
            SpiralAxis::Flat { center, normal } => (center, center, normal, 0.0),
            SpiralAxis::AroundCurve { .. } => {
                unreachable!("around-curve spirals return before axial construction")
            }
        };
        let (frame, start_radius) =
            axial_primitive_frame(axis_start, options.radii[0], axis, tolerance)?;
        let end_radius = axial_primitive_radius_value(axis_end, options.radii[1], frame)?;
        if start_radius < 0.0 || end_radius < 0.0 {
            return Err(GeometryError::InvalidSpiralDimensions.into());
        }
        let turn_count = match options.advance {
            SpiralAdvance::Turns(turn_count) => turn_count,
            SpiralAdvance::Pitch(pitch) => height / pitch,
        };
        let signed_turn_count = if options.reverse_twist {
            -turn_count
        } else {
            turn_count
        };
        let curve =
            NurbsCurve::try_spiral(frame, height, signed_turn_count, [start_radius, end_radius])?;
        let id = document.add_geometry(Geometry::NurbsCurve(curve))?;
        Ok(format!(
            "Added NURBS spiral {id} (radii {start_radius:.6} to {end_radius:.6}, height {height:.6}, turns {turn_count:.6}{})",
            if options.reverse_twist {
                ", reverse twist"
            } else {
                ""
            }
        ))
    }
}

struct CatenaryCommand;

impl Command for CatenaryCommand {
    fn name(&self) -> &'static str {
        "Catenary"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let options = parse_catenary_options(arguments)?;
        let solution = try_catenary(
            options.start,
            options.end,
            options.axis_direction,
            options.construction,
            options.output,
            options.point_count,
            document.tolerance(),
        )?;
        let apex = solution.apex();
        let parameter = solution.parameter();
        let length = solution.length();
        let apex_id = if options.mark_apex {
            Some(document.add_geometry(Geometry::Point(apex))?)
        } else {
            None
        };
        let (curve_id, representation) = match solution.into_curve() {
            CatenaryCurve::Smooth(curve) => (
                document.add_geometry(Geometry::NurbsCurve(curve))?,
                "smooth NURBS",
            ),
            CatenaryCurve::Polyline(polyline) => (
                document.add_geometry(Geometry::Polyline(polyline))?,
                "polyline",
            ),
        };
        Ok(format!(
            "Added {representation} catenary {curve_id} (parameter {parameter:.6}, length {length:.6}, {} points){}",
            options.point_count,
            apex_id.map_or_else(String::new, |id| format!(" and apex point {id}"))
        ))
    }
}

fn curve_radius_value(
    sample: CurveSample,
    radius: AxialPrimitiveRadius,
) -> Result<Real, CommandError> {
    match radius {
        AxialPrimitiveRadius::Numeric(radius) => Ok(radius),
        AxialPrimitiveRadius::Point(point) => {
            let vector = sample.point().vector_to(point)?;
            let tangent_distance = vector.dot(sample.tangent().as_vector())?;
            let tangent = sample.tangent().as_vector().scaled(tangent_distance)?;
            Vector3::try_new(
                vector.x() - tangent.x(),
                vector.y() - tangent.y(),
                vector.z() - tangent.z(),
            )?
            .length()
            .map_err(Into::into)
        }
    }
}

fn spiral_curve_path(
    document: &Document,
    path_name: Option<&str>,
) -> Result<(Geometry, ObjectId), CommandError> {
    let path_id = if let Some(name) = path_name {
        let matches = document
            .objects()
            .filter(|object| {
                object
                    .attributes()
                    .name()
                    .is_some_and(|candidate| candidate.eq_ignore_ascii_case(name))
            })
            .map(|object| object.id())
            .collect::<Vec<_>>();
        match matches.as_slice() {
            [] => return Err(CommandError::SpiralPathNotFound(name.to_owned())),
            [id] => *id,
            _ => return Err(CommandError::AmbiguousSpiralPath(name.to_owned())),
        }
    } else {
        document
            .selected_object_ids()
            .last()
            .ok_or(CommandError::SpiralPathRequired)?
    };
    let path = document
        .object(path_id)
        .expect("resolved spiral path identifiers are present");
    if geometry_curve_ref(path.geometry()).is_none() {
        return Err(CommandError::SpiralPathNotCurve);
    }
    Ok((path.geometry().clone(), path_id))
}

struct TruncatedConeCommand;

impl Command for TruncatedConeCommand {
    fn name(&self) -> &'static str {
        "TruncatedCone"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let options = parse_truncated_cone_options(arguments)?;
        let tolerance = document.tolerance();
        let (base_frame, base_radius) =
            axial_primitive_frame(options.center, options.base_radius, options.axis, tolerance)?;
        let direction = base_frame
            .z_axis()
            .as_vector()
            .scaled(if options.height > 0.0 { 1.0 } else { -1.0 })?;
        let frame = Frame3::try_from_x_and_normal(
            options.center,
            base_frame.x_axis().as_vector(),
            direction,
            tolerance,
        )?;
        let radii = [base_radius, options.end_radius];
        let height = options.height.abs();
        if options.solid {
            let brep = Brep::try_truncated_cone(frame, radii, height, tolerance)?;
            let id = document.add_geometry(Geometry::Brep(brep))?;
            Ok(format!(
                "Added closed B-rep truncated cone {id} (radii {base_radius:.6} to {:.6}, height {:.6})",
                options.end_radius, options.height
            ))
        } else {
            let surface = NurbsSurface::try_truncated_cone(frame, radii, height)?;
            let id = document.add_geometry(Geometry::NurbsSurface(surface))?;
            Ok(format!(
                "Added open NURBS truncated cone {id} (radii {base_radius:.6} to {:.6}, height {:.6})",
                options.end_radius, options.height
            ))
        }
    }
}

