struct SplitDisjointMeshCommand;

impl Command for SplitDisjointMeshCommand {
    fn name(&self) -> &'static str {
        "SplitDisjointMesh"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        require_consumed(arguments, 0, "SplitDisjointMesh")?;
        let selected_ids = document.selected_object_ids().collect::<Vec<_>>();
        if selected_ids.is_empty() {
            return Err(CommandError::NoObjectsSelected);
        }
        let inputs = selected_ids
            .into_iter()
            .map(|id| {
                let object = document
                    .object(id)
                    .expect("selected object identities belong to the document");
                let Geometry::Mesh(mesh) = object.geometry() else {
                    return Err(CommandError::UnsupportedSplitDisjointMeshGeometry);
                };
                let group_ids = document
                    .groups()
                    .filter(|group| group.members().any(|member| member == id))
                    .map(|group| group.id())
                    .collect();
                Ok(SplitMeshInput {
                    id,
                    attributes: object.attributes().clone(),
                    group_ids,
                    pieces: mesh.disjoint_pieces(),
                })
            })
            .collect::<Result<Vec<_>, CommandError>>()?;
        let split_mesh_count = inputs.iter().filter(|input| input.pieces.len() > 1).count();
        if split_mesh_count == 0 {
            return Err(CommandError::NoDisjointMeshes);
        }
        let unchanged_mesh_count = inputs.len() - split_mesh_count;
        let piece_count = inputs
            .iter()
            .filter(|input| input.pieces.len() > 1)
            .map(|input| input.pieces.len())
            .sum::<usize>();

        let replacements = inputs
            .iter()
            .filter(|input| input.pieces.len() > 1)
            .map(|input| (input.id, Geometry::Mesh(input.pieces[0].clone())))
            .collect::<Vec<_>>();
        let replaced = document.replace_object_geometries(replacements)?;
        debug_assert_eq!(replaced, split_mesh_count);

        let mut output_ids = Vec::with_capacity(inputs.len() + piece_count - split_mesh_count);
        let mut group_additions = BTreeMap::<GroupId, Vec<ObjectId>>::new();
        for input in inputs {
            output_ids.push(input.id);
            if input.pieces.len() <= 1 {
                continue;
            }
            for piece in input.pieces.into_iter().skip(1) {
                let id = document.add_geometry_with_attributes(
                    Geometry::Mesh(piece),
                    input.attributes.clone(),
                )?;
                output_ids.push(id);
                for group_id in &input.group_ids {
                    group_additions.entry(*group_id).or_default().push(id);
                }
            }
        }
        for (group_id, additions) in group_additions {
            document.add_group_members(group_id, additions)?;
        }
        replace_selection(document, output_ids)?;
        Ok(format!(
            "Split {split_mesh_count} mesh(es) into {piece_count} piece(s); {unchanged_mesh_count} mesh(es) unchanged"
        ))
    }
}

struct SplitMeshInput {
    id: ObjectId,
    attributes: ObjectAttributes,
    group_ids: Vec<GroupId>,
    pieces: Vec<TriangleMesh>,
}

const EXTRACT_MESH_EDGES_USAGE: &str = "ExtractMeshEdges [ExtractBy=Unwelded|BreakAngle|Naked] [GreaterThanAngle=degrees] [LessThanAngle=degrees] [JoinResults=Yes|No]";

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ExtractMeshEdgeKind {
    Unwelded,
    BreakAngle,
    Naked,
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct ExtractMeshEdgesOptions {
    kind: ExtractMeshEdgeKind,
    greater_than_degrees: Real,
    less_than_degrees: Real,
    join_results: bool,
}

impl ExtractMeshEdgesOptions {
    fn filter(self) -> MeshEdgeFilter {
        match self.kind {
            ExtractMeshEdgeKind::Unwelded => MeshEdgeFilter::Unwelded,
            ExtractMeshEdgeKind::Naked => MeshEdgeFilter::Naked,
            ExtractMeshEdgeKind::BreakAngle => MeshEdgeFilter::FaceAngle {
                greater_than_radians: self.greater_than_degrees.to_radians(),
                less_than_radians: self.less_than_degrees.to_radians(),
            },
        }
    }
}

struct ExtractMeshEdgesCommand;

impl Command for ExtractMeshEdgesCommand {
    fn name(&self) -> &'static str {
        "ExtractMeshEdges"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let options = parse_extract_mesh_edges_arguments(arguments)?;
        let mut staged = Vec::new();
        let mut source_count = 0_usize;
        for object in document.selected_objects() {
            let Geometry::Mesh(mesh) = object.geometry() else {
                return Err(CommandError::UnsupportedExtractMeshEdgesGeometry);
            };
            source_count += 1;
            if options.join_results {
                staged.extend(
                    mesh.filtered_edge_polylines(options.filter(), document.tolerance())?
                        .into_iter()
                        .map(Geometry::Polyline),
                );
            } else {
                staged.extend(
                    mesh.filtered_edge_lines(options.filter(), document.tolerance())?
                        .into_iter()
                        .map(Geometry::Line),
                );
            }
            if staged.len() > MAX_SPAN_OUTPUT_OBJECTS {
                return Err(too_many_span_outputs("ExtractMeshEdges"));
            }
        }
        if source_count == 0 {
            return Err(CommandError::NoObjectsSelected);
        }
        if staged.is_empty() {
            return Err(CommandError::NoExtractableMeshEdges);
        }

        let output_count = staged.len();
        let layer = document.current_layer_id();
        let mut output_ids = Vec::with_capacity(output_count);
        for geometry in staged {
            output_ids.push(
                document
                    .add_geometry_with_attributes(geometry, ObjectAttributes::on_layer(layer))?,
            );
        }
        document.select_objects_direct(output_ids, SelectionMode::Add)?;
        Ok(format!(
            "Extracted {output_count} mesh edge curve(s) from {source_count} mesh(es)"
        ))
    }
}

fn parse_extract_mesh_edges_arguments(
    arguments: &[&str],
) -> Result<ExtractMeshEdgesOptions, CommandError> {
    let mut options = ExtractMeshEdgesOptions {
        kind: ExtractMeshEdgeKind::Unwelded,
        greater_than_degrees: 0.0,
        less_than_degrees: 180.0,
        join_results: false,
    };
    let mut extract_by_seen = false;
    let mut greater_seen = false;
    let mut less_seen = false;
    let mut join_seen = false;
    let mut index = 0;
    while index < arguments.len() {
        let argument = arguments[index];
        let (name, value, consumed) = if let Some((name, value)) = argument.split_once('=') {
            (name, value, 1)
        } else {
            let value = arguments
                .get(index + 1)
                .ok_or(CommandError::Usage(EXTRACT_MESH_EDGES_USAGE))?;
            (argument, *value, 2)
        };
        if option_name_eq(name, "ExtractBy") && !extract_by_seen {
            let value = value.trim_start_matches('_');
            options.kind = if value.eq_ignore_ascii_case("Unwelded") {
                ExtractMeshEdgeKind::Unwelded
            } else if value.eq_ignore_ascii_case("BreakAngle") {
                ExtractMeshEdgeKind::BreakAngle
            } else if value.eq_ignore_ascii_case("Naked") {
                ExtractMeshEdgeKind::Naked
            } else {
                return Err(CommandError::Usage(EXTRACT_MESH_EDGES_USAGE));
            };
            extract_by_seen = true;
        } else if (option_name_eq(name, "GreaterThanAngle") || option_name_eq(name, "GreaterThan"))
            && !greater_seen
        {
            options.greater_than_degrees = parse_finite_real(value)?;
            greater_seen = true;
        } else if (option_name_eq(name, "LessThanAngle") || option_name_eq(name, "LessThan"))
            && !less_seen
        {
            options.less_than_degrees = parse_finite_real(value)?;
            less_seen = true;
        } else if option_name_eq(name, "JoinResults") && !join_seen {
            options.join_results =
                parse_yes_no(value).ok_or(CommandError::Usage(EXTRACT_MESH_EDGES_USAGE))?;
            join_seen = true;
        } else {
            return Err(CommandError::Usage(EXTRACT_MESH_EDGES_USAGE));
        }
        index += consumed;
    }
    if (greater_seen || less_seen) && options.kind != ExtractMeshEdgeKind::BreakAngle {
        return Err(CommandError::Usage(EXTRACT_MESH_EDGES_USAGE));
    }
    if options.kind == ExtractMeshEdgeKind::BreakAngle
        && !(options.greater_than_degrees >= 0.0
            && options.greater_than_degrees < options.less_than_degrees
            && options.less_than_degrees <= 180.0)
    {
        return Err(GeometryError::InvalidMeshFaceAngleInterval.into());
    }
    Ok(options)
}

const EXTRACT_MESH_FACES_USAGE: &str =
    "ExtractMeshFaces (point|Faces=All|Faces=0,2,...) [MakeCopy=Yes|No]";

#[derive(Clone, Debug, PartialEq)]
enum FaceSelection {
    Point(Point3),
    Faces(SurfaceFaceIndices),
}

#[derive(Clone, Copy)]
enum FaceEditCommand {
    ExtractMeshFaces,
    DeleteFaces,
}

impl FaceEditCommand {
    fn face_index_out_of_range(self, face: usize, face_count: usize) -> CommandError {
        match self {
            Self::ExtractMeshFaces => {
                CommandError::ExtractMeshFacesFaceIndexOutOfRange { face, face_count }
            }
            Self::DeleteFaces => CommandError::DeleteFacesFaceIndexOutOfRange { face, face_count },
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
struct ExtractMeshFacesOptions {
    selection: FaceSelection,
    make_copy: bool,
}

struct ExtractMeshFacesCommand;

struct MeshFaceSource {
    id: ObjectId,
    mesh: TriangleMesh,
    attributes: ObjectAttributes,
    group_ids: Vec<GroupId>,
}

struct ExtractMeshFacesPlan {
    source: ObjectId,
    remainder: Option<TriangleMesh>,
    extracted: TriangleMesh,
    attributes: ObjectAttributes,
    group_ids: Vec<GroupId>,
}

impl Command for ExtractMeshFacesCommand {
    fn name(&self) -> &'static str {
        "ExtractMeshFaces"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let options = parse_extract_mesh_faces_arguments(arguments)?;
        let sources = selected_mesh_face_sources(document, || {
            CommandError::UnsupportedExtractMeshFacesGeometry
        })?;
        if sources.is_empty() {
            return Err(CommandError::NoObjectsSelected);
        }

        let selections = selected_mesh_faces(
            &sources,
            &options.selection,
            FaceEditCommand::ExtractMeshFaces,
        )?;
        if selections.len() > MAX_SPAN_OUTPUT_OBJECTS {
            return Err(too_many_span_outputs("ExtractMeshFaces"));
        }
        let mut extracted_face_count = 0_usize;
        let mut plans = Vec::with_capacity(selections.len());
        for (source_index, face_indices) in selections {
            extracted_face_count = extracted_face_count
                .checked_add(face_indices.len())
                .ok_or_else(|| too_many_span_outputs("ExtractMeshFaces"))?;
            let source = &sources[source_index];
            let (remainder, extracted) = source.mesh.extract_faces(&face_indices)?.into_parts();
            plans.push(ExtractMeshFacesPlan {
                source: source.id,
                remainder,
                extracted,
                attributes: source.attributes.clone(),
                group_ids: source.group_ids.clone(),
            });
        }
        let source_count = plans.len();

        if !options.make_copy {
            document.replace_object_geometries(plans.iter().map(|plan| {
                (
                    plan.source,
                    Geometry::Mesh(plan.remainder.as_ref().unwrap_or(&plan.extracted).clone()),
                )
            }))?;
        }

        let mut output_ids = Vec::with_capacity(source_count);
        let mut group_additions = BTreeMap::<GroupId, Vec<ObjectId>>::new();
        for plan in plans {
            if !options.make_copy && plan.remainder.is_none() {
                output_ids.push(plan.source);
                continue;
            }
            let output = document
                .add_geometry_with_attributes(Geometry::Mesh(plan.extracted), plan.attributes)?;
            output_ids.push(output);
            for group_id in plan.group_ids {
                group_additions.entry(group_id).or_default().push(output);
            }
        }
        for (group_id, additions) in group_additions {
            document.add_group_members(group_id, additions)?;
        }
        document.select_objects_direct(output_ids, SelectionMode::Replace)?;
        Ok(format!(
            "Extracted {extracted_face_count} mesh face(s) from {source_count} mesh(es); source faces {}",
            if options.make_copy {
                "copied"
            } else {
                "removed"
            }
        ))
    }
}

fn selected_mesh_face_sources(
    document: &Document,
    unsupported_geometry: impl Fn() -> CommandError,
) -> Result<Vec<MeshFaceSource>, CommandError> {
    document
        .selected_object_ids()
        .map(|id| {
            let object = document
                .object(id)
                .expect("selected object identities belong to the document");
            let Geometry::Mesh(mesh) = object.geometry() else {
                return Err(unsupported_geometry());
            };
            let group_ids = document
                .groups()
                .filter(|group| group.members().any(|member| member == id))
                .map(|group| group.id())
                .collect();
            Ok(MeshFaceSource {
                id,
                mesh: mesh.clone(),
                attributes: object.attributes().clone(),
                group_ids,
            })
        })
        .collect()
}

fn selected_mesh_faces(
    sources: &[MeshFaceSource],
    selection: &FaceSelection,
    command: FaceEditCommand,
) -> Result<Vec<(usize, Vec<usize>)>, CommandError> {
    match selection {
        FaceSelection::Faces(selection) => sources
            .iter()
            .enumerate()
            .map(|(source_index, source)| {
                let face_count = source.mesh.face_count();
                let face_indices = match selection {
                    SurfaceFaceIndices::All => (0..face_count).collect(),
                    SurfaceFaceIndices::Indices(indices) => {
                        if let Some(&face) = indices.iter().find(|&&face| face >= face_count) {
                            return Err(command.face_index_out_of_range(face, face_count));
                        }
                        indices.clone()
                    }
                };
                Ok((source_index, face_indices))
            })
            .collect(),
        FaceSelection::Point(target) => {
            let mut best = None;
            for (source_index, source) in sources.iter().enumerate() {
                for face_index in 0..source.mesh.face_count() {
                    let point = source.mesh.closest_point_on_face(face_index, *target)?;
                    let distance = point.distance_to(*target)?;
                    if best.is_none_or(|(best_distance, _, _)| distance < best_distance) {
                        best = Some((distance, source_index, face_index));
                    }
                }
            }
            let (_, source, face) =
                best.expect("every selected validated mesh has at least one face");
            Ok(vec![(source, vec![face])])
        }
    }
}

fn parse_extract_mesh_faces_arguments(
    arguments: &[&str],
) -> Result<ExtractMeshFacesOptions, CommandError> {
    let mut make_copy = false;
    let mut face_selection = None;
    let mut make_copy_seen = false;
    let mut positional = Vec::new();
    let mut index = 0;
    while index < arguments.len() {
        let argument = arguments[index];
        let option = if let Some((name, value)) = argument.split_once('=') {
            Some((name, value, 1))
        } else if option_name_eq(argument, "MakeCopy")
            || option_name_eq(argument, "Faces")
            || option_name_eq(argument, "FaceIndices")
        {
            let value = arguments
                .get(index + 1)
                .ok_or(CommandError::Usage(EXTRACT_MESH_FACES_USAGE))?;
            Some((argument, *value, 2))
        } else {
            None
        };
        let Some((name, value, consumed)) = option else {
            positional.push(argument);
            index += 1;
            continue;
        };
        if option_name_eq(name, "MakeCopy") && !make_copy_seen {
            make_copy = parse_yes_no(value).ok_or(CommandError::Usage(EXTRACT_MESH_FACES_USAGE))?;
            make_copy_seen = true;
        } else if (option_name_eq(name, "Faces") || option_name_eq(name, "FaceIndices"))
            && face_selection.is_none()
        {
            face_selection = Some(parse_surface_face_indices(value, EXTRACT_MESH_FACES_USAGE)?);
        } else {
            return Err(CommandError::Usage(EXTRACT_MESH_FACES_USAGE));
        }
        index += consumed;
    }
    let selection = finish_face_selection(face_selection, &positional, EXTRACT_MESH_FACES_USAGE)?;
    Ok(ExtractMeshFacesOptions {
        selection,
        make_copy,
    })
}

const DELETE_FACES_USAGE: &str = "DeleteFaces (point|Faces=All|Faces=0,2,...)";

struct DeleteFacesCommand;

struct DeleteFacesSource {
    id: ObjectId,
    geometry: Geometry,
}

struct DeleteFacesPlan {
    source: ObjectId,
    remainder: Option<Geometry>,
}

impl Command for DeleteFacesCommand {
    fn name(&self) -> &'static str {
        "DeleteFaces"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let selection = parse_delete_faces_arguments(arguments)?;
        let sources = document
            .selected_objects()
            .map(|object| {
                if !matches!(object.geometry(), Geometry::Mesh(_) | Geometry::Brep(_)) {
                    return Err(CommandError::UnsupportedDeleteFacesGeometry);
                }
                Ok(DeleteFacesSource {
                    id: object.id(),
                    geometry: object.geometry().clone(),
                })
            })
            .collect::<Result<Vec<_>, CommandError>>()?;
        if sources.is_empty() {
            return Err(CommandError::NoObjectsSelected);
        }
        let selections = selected_delete_faces(&sources, &selection, document.tolerance())?;
        let deleted_face_count = selections
            .iter()
            .map(|(_, faces)| faces.len())
            .sum::<usize>();
        let plans = selections
            .into_iter()
            .map(|(source_index, face_indices)| {
                let source = &sources[source_index];
                let remainder = match &source.geometry {
                    Geometry::Mesh(mesh) => mesh.delete_faces(&face_indices)?.map(Geometry::Mesh),
                    Geometry::Brep(brep) => {
                        let deleted = face_indices.iter().copied().collect::<BTreeSet<_>>();
                        let remainder_faces = (0..brep.faces().len())
                            .filter(|face| !deleted.contains(face))
                            .collect::<Vec<_>>();
                        if remainder_faces.is_empty() {
                            None
                        } else {
                            Some(Geometry::Brep(
                                brep.sub_brep(&remainder_faces, document.tolerance())?,
                            ))
                        }
                    }
                    _ => unreachable!("DeleteFaces sources were validated above"),
                };
                Ok(DeleteFacesPlan {
                    source: source.id,
                    remainder,
                })
            })
            .collect::<Result<Vec<_>, CommandError>>()?;
        let source_count = plans.len();

        document.replace_object_geometries(plans.iter().filter_map(|plan| {
            plan.remainder
                .as_ref()
                .map(|remainder| (plan.source, remainder.clone()))
        }))?;
        for plan in plans {
            if plan.remainder.is_none() {
                document.delete_object(plan.source)?;
            }
        }
        document.clear_selection();
        Ok(format!(
            "Deleted {deleted_face_count} face(s) from {source_count} object(s)"
        ))
    }
}

fn selected_delete_faces(
    sources: &[DeleteFacesSource],
    selection: &FaceSelection,
    tolerance: Tolerance,
) -> Result<Vec<(usize, Vec<usize>)>, CommandError> {
    match selection {
        FaceSelection::Faces(selection) => sources
            .iter()
            .enumerate()
            .map(|(source_index, source)| {
                let face_count = match &source.geometry {
                    Geometry::Mesh(mesh) => mesh.face_count(),
                    Geometry::Brep(brep) => brep.faces().len(),
                    _ => unreachable!("DeleteFaces sources were validated above"),
                };
                let face_indices = match selection {
                    SurfaceFaceIndices::All => (0..face_count).collect(),
                    SurfaceFaceIndices::Indices(indices) => {
                        if let Some(&face) = indices.iter().find(|&&face| face >= face_count) {
                            return Err(FaceEditCommand::DeleteFaces
                                .face_index_out_of_range(face, face_count));
                        }
                        indices.clone()
                    }
                };
                Ok((source_index, face_indices))
            })
            .collect(),
        FaceSelection::Point(target) => {
            let mut best: Option<(Real, usize, usize)> = None;
            for (source_index, source) in sources.iter().enumerate() {
                let candidate = match &source.geometry {
                    Geometry::Mesh(mesh) => {
                        let mut nearest: Option<(Real, usize)> = None;
                        for face in 0..mesh.face_count() {
                            let point = mesh.closest_point_on_face(face, *target)?;
                            let distance = point.distance_to(*target)?;
                            if nearest.is_none_or(|(best_distance, _)| distance < best_distance) {
                                nearest = Some((distance, face));
                            }
                        }
                        nearest
                    }
                    Geometry::Brep(brep) => brep
                        .closest_face_parameters(*target, tolerance)?
                        .map(|(face, u, v)| {
                            brep.faces()[face]
                                .surface()
                                .evaluate(u, v)
                                .and_then(|point| point.distance_to(*target))
                                .map(|distance| (distance, face))
                        })
                        .transpose()?,
                    _ => unreachable!("DeleteFaces sources were validated above"),
                };
                let Some((distance, face)) = candidate else {
                    continue;
                };
                if best.is_none_or(|(best_distance, _, _)| distance < best_distance) {
                    best = Some((distance, source_index, face));
                }
            }
            let Some((_, source, face)) = best else {
                return Err(CommandError::NoDeleteFaceAtLocation);
            };
            Ok(vec![(source, vec![face])])
        }
    }
}

fn parse_delete_faces_arguments(arguments: &[&str]) -> Result<FaceSelection, CommandError> {
    let mut face_selection = None;
    let mut positional = Vec::new();
    let mut index = 0;
    while index < arguments.len() {
        let argument = arguments[index];
        let option = if let Some((name, value)) = argument.split_once('=') {
            Some((name, value, 1))
        } else if option_name_eq(argument, "Faces") || option_name_eq(argument, "FaceIndices") {
            let value = arguments
                .get(index + 1)
                .ok_or(CommandError::Usage(DELETE_FACES_USAGE))?;
            Some((argument, *value, 2))
        } else {
            None
        };
        let Some((name, value, consumed)) = option else {
            positional.push(argument);
            index += 1;
            continue;
        };
        if (option_name_eq(name, "Faces") || option_name_eq(name, "FaceIndices"))
            && face_selection.is_none()
        {
            face_selection = Some(parse_surface_face_indices(value, DELETE_FACES_USAGE)?);
        } else {
            return Err(CommandError::Usage(DELETE_FACES_USAGE));
        }
        index += consumed;
    }
    finish_face_selection(face_selection, &positional, DELETE_FACES_USAGE)
}

fn finish_face_selection(
    face_selection: Option<SurfaceFaceIndices>,
    positional: &[&str],
    usage: &'static str,
) -> Result<FaceSelection, CommandError> {
    if let Some(faces) = face_selection {
        require_consumed(positional, 0, usage)?;
        Ok(FaceSelection::Faces(faces))
    } else {
        let (point, consumed) = parse_point(positional)?;
        require_consumed(positional, consumed, usage)?;
        Ok(FaceSelection::Point(point))
    }
}

struct TriangulateMeshCommand;

impl Command for TriangulateMeshCommand {
    fn name(&self) -> &'static str {
        "TriangulateMesh"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        require_consumed(arguments, 0, "TriangulateMesh")?;
        if document.selected_object_count() == 0 {
            return Err(CommandError::NoObjectsSelected);
        }
        let staged = document
            .selected_objects()
            .map(|object| {
                let Geometry::Mesh(mesh) = object.geometry() else {
                    return Err(CommandError::UnsupportedTriangulateMeshGeometry);
                };
                let (triangulated, quad_count) = mesh.triangulate_quads(document.tolerance())?;
                Ok((object.id(), triangulated, quad_count))
            })
            .collect::<Result<Vec<_>, CommandError>>()?;
        let changed_mesh_count = staged
            .iter()
            .filter(|(_, _, quad_count)| *quad_count > 0)
            .count();
        let converted_quad_count = staged
            .iter()
            .map(|(_, _, quad_count)| quad_count)
            .sum::<usize>();
        document.replace_object_geometries(
            staged
                .iter()
                .filter(|(_, _, quad_count)| *quad_count > 0)
                .map(|(id, mesh, _)| (*id, Geometry::Mesh(mesh.clone()))),
        )?;
        Ok(format!(
            "Triangulated {converted_quad_count} quadrilateral face(s) in {changed_mesh_count} mesh(es); {} mesh(es) unchanged",
            staged.len() - changed_mesh_count
        ))
    }
}

const SWAP_MESH_EDGE_USAGE: &str = "SwapMeshEdge (point|Edge=index)";

#[derive(Clone, Debug, PartialEq)]
enum MeshTopologyEdgeSelection {
    Point(Point3),
    Edge(usize),
}

struct SwapMeshEdgeCommand;

impl Command for SwapMeshEdgeCommand {
    fn name(&self) -> &'static str {
        "SwapMeshEdge"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let selection = parse_mesh_topology_edge_arguments(arguments, SWAP_MESH_EDGE_USAGE)?;
        let sources = document
            .selected_objects()
            .map(|object| {
                let Geometry::Mesh(mesh) = object.geometry() else {
                    return Err(CommandError::UnsupportedSwapMeshEdgeGeometry);
                };
                Ok(MeshTopologySource {
                    id: object.id(),
                    mesh: mesh.clone(),
                })
            })
            .collect::<Result<Vec<_>, CommandError>>()?;
        if sources.is_empty() {
            return Err(CommandError::NoObjectsSelected);
        }

        let selections = selected_swap_mesh_edges(&sources, &selection, document.tolerance())?;
        let mesh_count = sources.len();
        let mut replacements = Vec::new();
        for (source_index, edge_index) in selections {
            let source = &sources[source_index];
            if let Some(swapped) = source
                .mesh
                .swap_topology_edge(edge_index, document.tolerance())?
            {
                replacements.push((source.id, Geometry::Mesh(swapped)));
            }
        }
        if replacements.is_empty() {
            return Err(CommandError::NoSwappableMeshEdges);
        }
        let swapped_edge_count = replacements.len();
        let changed_mesh_count = document.replace_object_geometries(replacements)?;
        Ok(format!(
            "Swapped {swapped_edge_count} mesh edge(s) in {changed_mesh_count} mesh(es); {} mesh(es) unchanged",
            mesh_count - changed_mesh_count
        ))
    }
}

fn selected_swap_mesh_edges(
    sources: &[MeshTopologySource],
    selection: &MeshTopologyEdgeSelection,
    tolerance: Tolerance,
) -> Result<Vec<(usize, usize)>, CommandError> {
    match selection {
        MeshTopologyEdgeSelection::Edge(edge) => sources
            .iter()
            .enumerate()
            .map(|(source_index, source)| {
                let edge_count = source.mesh.topology().edge_count();
                if *edge >= edge_count {
                    return Err(CommandError::SwapMeshEdgeIndexOutOfRange {
                        edge: *edge,
                        edge_count,
                    });
                }
                Ok((source_index, *edge))
            })
            .collect(),
        MeshTopologyEdgeSelection::Point(target) => {
            let Some((source, edge)) = closest_mesh_topology_edge(sources, *target, tolerance)?
            else {
                return Err(CommandError::NoSwappableMeshEdges);
            };
            Ok(vec![(source, edge)])
        }
    }
}

fn closest_mesh_topology_edge(
    sources: &[MeshTopologySource],
    target: Point3,
    tolerance: Tolerance,
) -> Result<Option<(usize, usize)>, GeometryError> {
    let mut best = None;
    for (source_index, source) in sources.iter().enumerate() {
        for (edge_index, edge) in source
            .mesh
            .wireframe_lines(tolerance)?
            .into_iter()
            .enumerate()
        {
            let closest = edge.closest_point(target, tolerance)?;
            let distance = closest.distance_to(target)?;
            if best.is_none_or(|(best_distance, _, _)| distance < best_distance) {
                best = Some((distance, source_index, edge_index));
            }
        }
    }
    Ok(best.map(|(_, source, edge)| (source, edge)))
}

fn parse_mesh_topology_edge_arguments(
    arguments: &[&str],
    usage: &'static str,
) -> Result<MeshTopologyEdgeSelection, CommandError> {
    let mut edge_selection = None;
    let mut positional = Vec::new();
    let mut index = 0;
    while index < arguments.len() {
        let argument = arguments[index];
        let option = if let Some((name, value)) = argument.split_once('=') {
            Some((name, value, 1))
        } else if option_name_eq(argument, "Edge") || option_name_eq(argument, "EdgeIndex") {
            let value = arguments.get(index + 1).ok_or(CommandError::Usage(usage))?;
            Some((argument, *value, 2))
        } else {
            None
        };
        if let Some((name, value, consumed)) = option {
            if (option_name_eq(name, "Edge") || option_name_eq(name, "EdgeIndex"))
                && edge_selection.is_none()
            {
                edge_selection = Some(
                    value
                        .trim_start_matches('_')
                        .parse::<usize>()
                        .map_err(|_| CommandError::Usage(usage))?,
                );
            } else {
                return Err(CommandError::Usage(usage));
            }
            index += consumed;
        } else {
            positional.push(argument);
            index += 1;
        }
    }
    if let Some(edge) = edge_selection {
        require_consumed(&positional, 0, usage)?;
        Ok(MeshTopologyEdgeSelection::Edge(edge))
    } else {
        if positional.is_empty() {
            return Err(CommandError::Usage(usage));
        }
        let (point, consumed) = parse_point(&positional)?;
        require_consumed(&positional, consumed, usage)?;
        Ok(MeshTopologyEdgeSelection::Point(point))
    }
}

const COLLAPSE_MESH_EDGE_USAGE: &str = "CollapseMeshEdge (point|Edge=index)";

struct CollapseMeshEdgeCommand;

impl Command for CollapseMeshEdgeCommand {
    fn name(&self) -> &'static str {
        "CollapseMeshEdge"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let selection = parse_mesh_topology_edge_arguments(arguments, COLLAPSE_MESH_EDGE_USAGE)?;
        let sources = document
            .selected_objects()
            .map(|object| {
                let Geometry::Mesh(mesh) = object.geometry() else {
                    return Err(CommandError::UnsupportedCollapseMeshEdgeGeometry);
                };
                Ok(MeshTopologySource {
                    id: object.id(),
                    mesh: mesh.clone(),
                })
            })
            .collect::<Result<Vec<_>, CommandError>>()?;
        if sources.is_empty() {
            return Err(CommandError::NoObjectsSelected);
        }

        let selections = selected_collapse_mesh_edges(&sources, &selection, document.tolerance())?;
        let plans = selections
            .into_iter()
            .map(|(source_index, edge_index)| {
                let source = &sources[source_index];
                Ok((
                    source.id,
                    source
                        .mesh
                        .collapse_topology_edge(edge_index, document.tolerance())?,
                ))
            })
            .collect::<Result<Vec<_>, CommandError>>()?;
        let collapsed_edge_count = plans.len();
        let deleted_mesh_count = plans
            .iter()
            .filter(|(_, remainder)| remainder.is_none())
            .count();
        let changed_mesh_count =
            document.replace_object_geometries(plans.iter().filter_map(|(id, remainder)| {
                remainder
                    .as_ref()
                    .map(|mesh| (*id, Geometry::Mesh(mesh.clone())))
            }))?;
        for (id, remainder) in plans {
            if remainder.is_none() {
                document.delete_object(id)?;
            }
        }
        Ok(format!(
            "Collapsed {collapsed_edge_count} mesh edge(s) in {} mesh(es); deleted {deleted_mesh_count} empty mesh(es)",
            changed_mesh_count + deleted_mesh_count
        ))
    }
}

fn selected_collapse_mesh_edges(
    sources: &[MeshTopologySource],
    selection: &MeshTopologyEdgeSelection,
    tolerance: Tolerance,
) -> Result<Vec<(usize, usize)>, CommandError> {
    match selection {
        MeshTopologyEdgeSelection::Edge(edge) => sources
            .iter()
            .enumerate()
            .map(|(source_index, source)| {
                let edge_count = source.mesh.topology().edge_count();
                if *edge >= edge_count {
                    return Err(CommandError::CollapseMeshEdgeIndexOutOfRange {
                        edge: *edge,
                        edge_count,
                    });
                }
                Ok((source_index, *edge))
            })
            .collect(),
        MeshTopologyEdgeSelection::Point(target) => {
            let Some((source, edge)) = closest_mesh_topology_edge(sources, *target, tolerance)?
            else {
                return Err(CommandError::NoCollapsibleMeshEdges);
            };
            Ok(vec![(source, edge)])
        }
    }
}

const SPLIT_MESH_EDGE_USAGE: &str =
    "SplitMeshEdge (edge-point split-point|Edge=index Parameter=number)";

#[derive(Clone, Debug, PartialEq)]
enum SplitMeshEdgeSelection {
    Points {
        edge_point: Point3,
        split_point: Point3,
    },
    Edge {
        edge: usize,
        parameter: Real,
    },
}

struct SplitMeshEdgeCommand;

impl Command for SplitMeshEdgeCommand {
    fn name(&self) -> &'static str {
        "SplitMeshEdge"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let selection = parse_split_mesh_edge_arguments(arguments)?;
        let sources = document
            .selected_objects()
            .map(|object| {
                let Geometry::Mesh(mesh) = object.geometry() else {
                    return Err(CommandError::UnsupportedSplitMeshEdgeGeometry);
                };
                Ok(MeshTopologySource {
                    id: object.id(),
                    mesh: mesh.clone(),
                })
            })
            .collect::<Result<Vec<_>, CommandError>>()?;
        if sources.is_empty() {
            return Err(CommandError::NoObjectsSelected);
        }

        let selections = selected_split_mesh_edges(&sources, &selection, document.tolerance())?;
        let replacements = selections
            .into_iter()
            .map(|(source_index, edge_index, parameter)| {
                let source = &sources[source_index];
                let split = source
                    .mesh
                    .split_topology_edge(edge_index, parameter, document.tolerance())?
                    .ok_or(CommandError::NoSplittableMeshEdges)?;
                Ok((source.id, Geometry::Mesh(split)))
            })
            .collect::<Result<Vec<_>, CommandError>>()?;
        let split_edge_count = replacements.len();
        let changed_mesh_count = document.replace_object_geometries(replacements)?;
        Ok(format!(
            "Split {split_edge_count} mesh edge(s) in {changed_mesh_count} mesh(es)"
        ))
    }
}

fn selected_split_mesh_edges(
    sources: &[MeshTopologySource],
    selection: &SplitMeshEdgeSelection,
    tolerance: Tolerance,
) -> Result<Vec<(usize, usize, Real)>, CommandError> {
    match selection {
        SplitMeshEdgeSelection::Edge { edge, parameter } => sources
            .iter()
            .enumerate()
            .map(|(source_index, source)| {
                let edge_count = source.mesh.topology().edge_count();
                if *edge >= edge_count {
                    return Err(CommandError::SplitMeshEdgeIndexOutOfRange {
                        edge: *edge,
                        edge_count,
                    });
                }
                Ok((source_index, *edge, *parameter))
            })
            .collect(),
        SplitMeshEdgeSelection::Points {
            edge_point,
            split_point,
        } => {
            let Some((source_index, edge_index)) =
                closest_mesh_topology_edge(sources, *edge_point, tolerance)?
            else {
                return Err(CommandError::NoSplittableMeshEdges);
            };
            let edge = sources[source_index].mesh.wireframe_lines(tolerance)?[edge_index];
            let parameter = edge.closest_parameter(*split_point, tolerance)?;
            Ok(vec![(source_index, edge_index, parameter)])
        }
    }
}

fn parse_split_mesh_edge_arguments(
    arguments: &[&str],
) -> Result<SplitMeshEdgeSelection, CommandError> {
    let mut edge = None;
    let mut parameter = None;
    let mut positional = Vec::new();
    let mut index = 0;
    while index < arguments.len() {
        let argument = arguments[index];
        let option = if let Some((name, value)) = argument.split_once('=') {
            Some((name, value, 1))
        } else if option_name_eq(argument, "Edge")
            || option_name_eq(argument, "EdgeIndex")
            || option_name_eq(argument, "Parameter")
        {
            let value = arguments
                .get(index + 1)
                .ok_or(CommandError::Usage(SPLIT_MESH_EDGE_USAGE))?;
            Some((argument, *value, 2))
        } else {
            None
        };
        let Some((name, value, consumed)) = option else {
            positional.push(argument);
            index += 1;
            continue;
        };
        if (option_name_eq(name, "Edge") || option_name_eq(name, "EdgeIndex")) && edge.is_none() {
            edge = Some(
                value
                    .trim_start_matches('_')
                    .parse::<usize>()
                    .map_err(|_| CommandError::Usage(SPLIT_MESH_EDGE_USAGE))?,
            );
        } else if option_name_eq(name, "Parameter") && parameter.is_none() {
            parameter = Some(parse_finite_real(value.trim_start_matches('_'))?);
        } else {
            return Err(CommandError::Usage(SPLIT_MESH_EDGE_USAGE));
        }
        index += consumed;
    }

    if edge.is_some() || parameter.is_some() {
        require_consumed(&positional, 0, SPLIT_MESH_EDGE_USAGE)?;
        let (Some(edge), Some(parameter)) = (edge, parameter) else {
            return Err(CommandError::Usage(SPLIT_MESH_EDGE_USAGE));
        };
        if !(0.0..=1.0).contains(&parameter) {
            return Err(CommandError::InvalidMeshEdgeSplitParameter(parameter));
        }
        Ok(SplitMeshEdgeSelection::Edge { edge, parameter })
    } else {
        let (edge_point, edge_consumed) = parse_point(&positional)?;
        let (split_point, split_consumed) = parse_point(&positional[edge_consumed..])?;
        require_consumed(
            &positional,
            edge_consumed + split_consumed,
            SPLIT_MESH_EDGE_USAGE,
        )?;
        Ok(SplitMeshEdgeSelection::Points {
            edge_point,
            split_point,
        })
    }
}

const FILL_MESH_HOLE_USAGE: &str = "FillMeshHole (point|Edge=index) [JoinMesh=Yes|No]";

#[derive(Clone, Debug, PartialEq)]
struct FillMeshHoleOptions {
    selection: MeshTopologyEdgeSelection,
    join_mesh: bool,
}

struct FillMeshHoleSource {
    id: ObjectId,
    mesh: TriangleMesh,
    attributes: ObjectAttributes,
}

struct FillMeshHolePlan {
    source: ObjectId,
    filled: TriangleMesh,
    patch: TriangleMesh,
    attributes: ObjectAttributes,
}

struct FillMeshHoleCommand;

impl Command for FillMeshHoleCommand {
    fn name(&self) -> &'static str {
        "FillMeshHole"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let options = parse_fill_mesh_hole_arguments(arguments)?;
        let sources = document
            .selected_objects()
            .map(|object| {
                let Geometry::Mesh(mesh) = object.geometry() else {
                    return Err(CommandError::UnsupportedFillMeshHoleGeometry);
                };
                Ok(FillMeshHoleSource {
                    id: object.id(),
                    mesh: mesh.clone(),
                    attributes: object.attributes().clone(),
                })
            })
            .collect::<Result<Vec<_>, CommandError>>()?;
        if sources.is_empty() {
            return Err(CommandError::NoObjectsSelected);
        }
        let topology_sources = sources
            .iter()
            .map(|source| MeshTopologySource {
                id: source.id,
                mesh: source.mesh.clone(),
            })
            .collect::<Vec<_>>();
        let selections = selected_fill_mesh_hole_edges(
            &topology_sources,
            &options.selection,
            document.tolerance(),
        )?;
        if selections.len() > MAX_SPAN_OUTPUT_OBJECTS {
            return Err(too_many_span_outputs("FillMeshHole"));
        }

        let mut plans = Vec::new();
        for (source_index, edge_index) in selections {
            let source = &sources[source_index];
            let Some(fill) = source
                .mesh
                .fill_topology_hole(edge_index, document.tolerance())?
            else {
                continue;
            };
            let (filled, patch) = fill.into_parts();
            plans.push(FillMeshHolePlan {
                source: source.id,
                filled,
                patch,
                attributes: source.attributes.clone(),
            });
        }
        if plans.is_empty() {
            return Err(CommandError::NoFillableMeshHoles);
        }
        let filled_face_count = plans
            .iter()
            .map(|plan| plan.patch.face_count())
            .sum::<usize>();
        let filled_hole_count = plans.len();

        if options.join_mesh {
            let changed_mesh_count = document.replace_object_geometries(
                plans
                    .into_iter()
                    .map(|plan| (plan.source, Geometry::Mesh(plan.filled))),
            )?;
            Ok(format!(
                "Filled {filled_hole_count} mesh hole(s) with {filled_face_count} triangle(s) in {changed_mesh_count} joined mesh(es)"
            ))
        } else {
            let mut output_ids = Vec::with_capacity(plans.len());
            for plan in plans {
                output_ids.push(
                    document.add_geometry_with_attributes(
                        Geometry::Mesh(plan.patch),
                        plan.attributes,
                    )?,
                );
            }
            document.select_objects_direct(output_ids, SelectionMode::Replace)?;
            Ok(format!(
                "Filled {filled_hole_count} mesh hole(s) with {filled_face_count} triangle(s) in separate patch mesh(es)"
            ))
        }
    }
}

fn selected_fill_mesh_hole_edges(
    sources: &[MeshTopologySource],
    selection: &MeshTopologyEdgeSelection,
    tolerance: Tolerance,
) -> Result<Vec<(usize, usize)>, CommandError> {
    match selection {
        MeshTopologyEdgeSelection::Edge(edge) => sources
            .iter()
            .enumerate()
            .map(|(source_index, source)| {
                let edge_count = source.mesh.topology().edge_count();
                if *edge >= edge_count {
                    return Err(CommandError::FillMeshHoleEdgeIndexOutOfRange {
                        edge: *edge,
                        edge_count,
                    });
                }
                Ok((source_index, *edge))
            })
            .collect(),
        MeshTopologyEdgeSelection::Point(target) => {
            let Some((source, edge)) = closest_mesh_topology_edge(sources, *target, tolerance)?
            else {
                return Err(CommandError::NoFillableMeshHoles);
            };
            Ok(vec![(source, edge)])
        }
    }
}

fn parse_fill_mesh_hole_arguments(arguments: &[&str]) -> Result<FillMeshHoleOptions, CommandError> {
    let mut edge = None;
    let mut join_mesh = true;
    let mut join_mesh_seen = false;
    let mut positional = Vec::new();
    let mut index = 0;
    while index < arguments.len() {
        let argument = arguments[index];
        let option = if let Some((name, value)) = argument.split_once('=') {
            Some((name, value, 1))
        } else if option_name_eq(argument, "Edge")
            || option_name_eq(argument, "EdgeIndex")
            || option_name_eq(argument, "JoinMesh")
        {
            let value = arguments
                .get(index + 1)
                .ok_or(CommandError::Usage(FILL_MESH_HOLE_USAGE))?;
            Some((argument, *value, 2))
        } else {
            None
        };
        let Some((name, value, consumed)) = option else {
            positional.push(argument);
            index += 1;
            continue;
        };
        if (option_name_eq(name, "Edge") || option_name_eq(name, "EdgeIndex")) && edge.is_none() {
            edge = Some(
                value
                    .trim_start_matches('_')
                    .parse::<usize>()
                    .map_err(|_| CommandError::Usage(FILL_MESH_HOLE_USAGE))?,
            );
        } else if option_name_eq(name, "JoinMesh") && !join_mesh_seen {
            join_mesh = parse_yes_no(value).ok_or(CommandError::Usage(FILL_MESH_HOLE_USAGE))?;
            join_mesh_seen = true;
        } else {
            return Err(CommandError::Usage(FILL_MESH_HOLE_USAGE));
        }
        index += consumed;
    }

    let selection = if let Some(edge) = edge {
        require_consumed(&positional, 0, FILL_MESH_HOLE_USAGE)?;
        MeshTopologyEdgeSelection::Edge(edge)
    } else {
        let (point, consumed) = parse_point(&positional)?;
        require_consumed(&positional, consumed, FILL_MESH_HOLE_USAGE)?;
        MeshTopologyEdgeSelection::Point(point)
    };
    Ok(FillMeshHoleOptions {
        selection,
        join_mesh,
    })
}

struct FillMeshHolesCommand;

impl Command for FillMeshHolesCommand {
    fn name(&self) -> &'static str {
        "FillMeshHoles"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        require_consumed(arguments, 0, "FillMeshHoles")?;
        let selected = document
            .selected_objects()
            .map(|object| (object.id(), object.geometry().clone()))
            .collect::<Vec<_>>();
        if selected.is_empty() {
            return Err(CommandError::NoObjectsSelected);
        }

        let selected_mesh_count = selected.len();
        let mut filled_hole_count = 0_usize;
        let mut filled_face_count = 0_usize;
        let mut replacements = Vec::new();
        for (id, geometry) in selected {
            let Geometry::Mesh(mesh) = geometry else {
                return Err(CommandError::UnsupportedFillMeshHolesGeometry);
            };
            let source_face_count = mesh.face_count();
            let (filled, hole_count) = mesh.fill_holes(document.tolerance())?;
            if hole_count == 0 {
                continue;
            }
            filled_hole_count = filled_hole_count
                .checked_add(hole_count)
                .ok_or(GeometryError::TooManyMeshFaces)?;
            filled_face_count = filled_face_count
                .checked_add(filled.face_count() - source_face_count)
                .ok_or(GeometryError::TooManyMeshFaces)?;
            replacements.push((id, Geometry::Mesh(filled)));
        }
        if replacements.is_empty() {
            return Err(CommandError::NoFillableMeshHoles);
        }

        let changed_mesh_count = document.replace_object_geometries(replacements)?;
        Ok(format!(
            "Filled {filled_hole_count} mesh hole(s) with {filled_face_count} triangle(s) in {changed_mesh_count} mesh(es); {} mesh(es) unchanged",
            selected_mesh_count - changed_mesh_count
        ))
    }
}

const EXTRACT_NON_MANIFOLD_USAGE: &str =
    "ExtractNonManifoldMeshEdges [ExtractHangingFacesOnly=Yes|No] [MinimumFaceCount=count]";

struct ExtractNonManifoldMeshEdgesCommand;

impl Command for ExtractNonManifoldMeshEdgesCommand {
    fn name(&self) -> &'static str {
        "ExtractNonManifoldMeshEdges"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let options = parse_extract_non_manifold_arguments(arguments)?;
        if document.selected_object_count() == 0 {
            return Err(CommandError::NoObjectsSelected);
        }
        let inputs = stage_selected_mesh_face_extractions(
            document,
            || CommandError::UnsupportedExtractNonManifoldGeometry,
            |mesh| {
                mesh.extract_non_manifold_faces(
                    options.minimum_face_count,
                    options.hanging_faces_only,
                )
            },
        )?;
        let counts = mesh_face_extraction_counts(&inputs);
        if counts.extracted_meshes == 0 {
            return Err(CommandError::NoNonManifoldMeshFaces);
        }
        apply_mesh_face_extractions(document, inputs, counts.extracted_meshes)?;
        Ok(format!(
            "Extracted {} face(s) from {} mesh(es); {} mesh(es) unchanged",
            counts.extracted_faces, counts.extracted_meshes, counts.unchanged_meshes
        ))
    }
}

struct MeshFaceExtractionInput {
    id: ObjectId,
    attributes: ObjectAttributes,
    group_ids: Vec<GroupId>,
    extraction: Option<(Option<TriangleMesh>, TriangleMesh)>,
}

#[derive(Clone, Copy)]
struct MeshFaceExtractionCounts {
    extracted_meshes: usize,
    unchanged_meshes: usize,
    extracted_faces: usize,
}

fn stage_selected_mesh_face_extractions(
    document: &Document,
    unsupported_geometry: impl Fn() -> CommandError,
    mut extract: impl FnMut(&TriangleMesh) -> Result<Option<MeshFaceExtraction>, GeometryError>,
) -> Result<Vec<MeshFaceExtractionInput>, CommandError> {
    document
        .selected_object_ids()
        .map(|id| {
            let object = document
                .object(id)
                .expect("selected object identities belong to the document");
            let Geometry::Mesh(mesh) = object.geometry() else {
                return Err(unsupported_geometry());
            };
            let group_ids = document
                .groups()
                .filter(|group| group.members().any(|member| member == id))
                .map(|group| group.id())
                .collect();
            Ok(MeshFaceExtractionInput {
                id,
                attributes: object.attributes().clone(),
                group_ids,
                extraction: extract(mesh)?.map(MeshFaceExtraction::into_parts),
            })
        })
        .collect()
}

fn mesh_face_extraction_counts(inputs: &[MeshFaceExtractionInput]) -> MeshFaceExtractionCounts {
    let extracted_meshes = inputs
        .iter()
        .filter(|input| input.extraction.is_some())
        .count();
    let extracted_faces = inputs
        .iter()
        .filter_map(|input| input.extraction.as_ref())
        .map(|(_, extracted)| extracted.face_count())
        .sum();
    MeshFaceExtractionCounts {
        extracted_meshes,
        unchanged_meshes: inputs.len() - extracted_meshes,
        extracted_faces,
    }
}

fn apply_mesh_face_extractions(
    document: &mut Document,
    inputs: Vec<MeshFaceExtractionInput>,
    extracted_mesh_count: usize,
) -> Result<(), CommandError> {
    let replacements = inputs
        .iter()
        .filter_map(|input| {
            input.extraction.as_ref().map(|(remainder, extracted)| {
                (
                    input.id,
                    Geometry::Mesh(remainder.as_ref().unwrap_or(extracted).clone()),
                )
            })
        })
        .collect::<Vec<_>>();
    let replaced = document.replace_object_geometries(replacements)?;
    debug_assert_eq!(replaced, extracted_mesh_count);

    let mut output_ids = Vec::with_capacity(inputs.len() + extracted_mesh_count);
    let mut group_additions = BTreeMap::<GroupId, Vec<ObjectId>>::new();
    for input in inputs {
        output_ids.push(input.id);
        let Some((remainder, extracted)) = input.extraction else {
            continue;
        };
        if remainder.is_none() {
            continue;
        }
        let id =
            document.add_geometry_with_attributes(Geometry::Mesh(extracted), input.attributes)?;
        output_ids.push(id);
        for group_id in input.group_ids {
            group_additions.entry(group_id).or_default().push(id);
        }
    }
    for (group_id, additions) in group_additions {
        document.add_group_members(group_id, additions)?;
    }
    replace_selection(document, output_ids)?;
    Ok(())
}

#[derive(Clone, Copy)]
struct ExtractNonManifoldOptions {
    hanging_faces_only: bool,
    minimum_face_count: usize,
}

fn parse_extract_non_manifold_arguments(
    arguments: &[&str],
) -> Result<ExtractNonManifoldOptions, CommandError> {
    let mut options = ExtractNonManifoldOptions {
        hanging_faces_only: false,
        minimum_face_count: 3,
    };
    let mut hanging_seen = false;
    let mut minimum_seen = false;
    let mut index = 0;
    while index < arguments.len() {
        let argument = arguments[index];
        let (name, value, consumed) = if let Some((name, value)) = argument.split_once('=') {
            (name, value, 1)
        } else {
            let value = arguments
                .get(index + 1)
                .ok_or(CommandError::Usage(EXTRACT_NON_MANIFOLD_USAGE))?;
            (argument, *value, 2)
        };
        let name = name.trim_start_matches('_');
        if name.eq_ignore_ascii_case("ExtractHangingFacesOnly") && !hanging_seen {
            options.hanging_faces_only =
                parse_yes_no(value).ok_or(CommandError::Usage(EXTRACT_NON_MANIFOLD_USAGE))?;
            hanging_seen = true;
        } else if name.eq_ignore_ascii_case("MinimumFaceCount") && !minimum_seen {
            options.minimum_face_count = value
                .parse::<usize>()
                .map_err(|_| CommandError::InvalidInteger(value.to_owned()))?;
            if options.minimum_face_count < 3 {
                return Err(GeometryError::InvalidNonManifoldMinimumFaceCount(
                    options.minimum_face_count,
                )
                .into());
            }
            minimum_seen = true;
        } else {
            return Err(CommandError::Usage(EXTRACT_NON_MANIFOLD_USAGE));
        }
        index += consumed;
    }
    Ok(options)
}

struct ExtractDuplicateMeshFacesCommand;

impl Command for ExtractDuplicateMeshFacesCommand {
    fn name(&self) -> &'static str {
        "ExtractDuplicateMeshFaces"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        require_consumed(arguments, 0, "ExtractDuplicateMeshFaces")?;
        if document.selected_object_count() == 0 {
            return Err(CommandError::NoObjectsSelected);
        }
        let inputs = stage_selected_mesh_face_extractions(
            document,
            || CommandError::UnsupportedExtractDuplicateMeshFacesGeometry,
            |mesh| Ok(mesh.extract_duplicate_faces()),
        )?;
        let counts = mesh_face_extraction_counts(&inputs);
        if counts.extracted_meshes == 0 {
            return Err(CommandError::NoDuplicateMeshFaces);
        }
        apply_mesh_face_extractions(document, inputs, counts.extracted_meshes)?;
        Ok(format!(
            "Extracted {} duplicate face(s) from {} mesh(es); {} mesh(es) unchanged",
            counts.extracted_faces, counts.extracted_meshes, counts.unchanged_meshes
        ))
    }
}

struct GroupCommand;

impl Command for GroupCommand {
    fn name(&self) -> &'static str {
        "Group"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let all = arguments
            .first()
            .is_some_and(|argument| argument.eq_ignore_ascii_case("all"));
        let name_arguments = if all { &arguments[1..] } else { arguments };
        let name = if name_arguments.is_empty() {
            document.next_unused_group_name()
        } else {
            name_arguments.join(" ")
        };
        let members: Vec<_> = if all {
            document
                .objects()
                .filter(|object| document.is_object_selectable(object.id()))
                .map(|object| object.id())
                .collect()
        } else {
            document.selected_object_ids().collect()
        };
        let member_count = members.len();
        let id = document.add_group(Some(name.clone()), members)?;
        Ok(format!(
            "Created group '{name}' {id} with {member_count} object(s)"
        ))
    }
}

const SET_OBJECT_NAME_USAGE: &str = "SetObjectName name [AppendCounter=Yes|No]";

struct SetObjectNameCommand;

impl Command for SetObjectNameCommand {
    fn name(&self) -> &'static str {
        "SetObjectName"
    }

    fn run(&self, document: &mut Document, arguments: &[&str]) -> Result<String, CommandError> {
        let (name, append_counter) = parse_set_object_name_arguments(arguments)?;
        let selected = document
            .objects()
            .filter(|object| document.is_selected(object.id()))
            .map(|object| object.id())
            .collect::<Vec<_>>();
        if selected.is_empty() {
            return Err(CommandError::NoObjectsSelected);
        }
        let has_name = name.is_some();
        let assignments = match name.as_ref() {
            Some(name) if append_counter => selected
                .iter()
                .enumerate()
                .map(|(index, id)| (*id, Some(format!("{name} {index}"))))
                .collect::<Vec<_>>(),
            _ => selected
                .iter()
                .map(|id| (*id, name.clone()))
                .collect::<Vec<_>>(),
        };
        document.set_object_names(assignments)?;
        Ok(if has_name {
            format!("Named {} object(s)", selected.len())
        } else {
            format!("Cleared names on {} object(s)", selected.len())
        })
    }
}

fn parse_set_object_name_arguments(
    arguments: &[&str],
) -> Result<(Option<String>, bool), CommandError> {
    let mut append_counter = false;
    let mut name_parts = Vec::new();
    for argument in arguments {
        let normalized = argument.trim_start_matches('_');
        if let Some((option, value)) = normalized.split_once('=')
            && option.eq_ignore_ascii_case("AppendCounter")
        {
            append_counter = parse_yes_no(value.trim_start_matches('_'))
                .ok_or(CommandError::Usage(SET_OBJECT_NAME_USAGE))?;
        } else {
            name_parts.push(*argument);
        }
    }
    if name_parts.is_empty() {
        return Err(CommandError::Usage(SET_OBJECT_NAME_USAGE));
    }
    let joined = name_parts.join(" ");
    let trimmed = joined.trim();
    let unquoted = if trimmed.len() >= 2 && trimmed.starts_with('"') && trimmed.ends_with('"') {
        &trimmed[1..trimmed.len() - 1]
    } else {
        trimmed
    };
    let name = (!unquoted.trim().is_empty()).then(|| unquoted.trim().to_owned());
    Ok((name, append_counter))
}

