    #[test]
    fn creates_exact_circles_and_oriented_three_point_arcs_atomically() {
        let registry = CommandRegistry::with_builtins();
        let mut document = Document::default();
        registry.execute(&mut document, "Circle 1,2,3 5").unwrap();
        registry
            .execute(&mut document, "Arc 1,0,0 0,-1,0 -1,0,0")
            .unwrap();

        let mut objects = document.objects();
        let Geometry::Circle(circle) = objects.next().unwrap().geometry() else {
            panic!("expected a circle")
        };
        assert_eq!(circle.center(), Point3::try_new(1.0, 2.0, 3.0).unwrap());
        assert_eq!(circle.radius(), 5.0);
        let Geometry::Arc(arc) = objects.next().unwrap().geometry() else {
            panic!("expected an arc")
        };
        assert!(
            document
                .tolerance()
                .approx_eq(arc.sweep_radians(), std::f64::consts::PI)
        );
        assert!(arc.point_at(0.5).unwrap().is_near(
            Point3::try_new(0.0, -1.0, 0.0).unwrap(),
            document.tolerance()
        ));
        drop(objects);
        assert_eq!(document.undo_label(), Some("Arc"));
        registry.execute(&mut document, "Undo").unwrap();
        assert_eq!(document.objects().len(), 1);

        assert!(registry.execute(&mut document, "Arc 0,0 1,0 2,0").is_err());
        assert_eq!(document.objects().len(), 1);
        assert_eq!(document.undo_label(), Some("Circle"));
    }

    #[test]
    fn sphere_creates_exact_opennurbs_surface_from_radius_or_point() {
        let registry = CommandRegistry::with_builtins();
        let mut document = Document::default();
        registry.execute(&mut document, "Sphere 1,2,3 2.5").unwrap();
        let sphere_id = document.objects().next().unwrap().id();
        assert!(!document.is_selected(sphere_id));
        let Geometry::NurbsSurface(surface) = document.object(sphere_id).unwrap().geometry() else {
            panic!("Sphere must create a NURBS surface")
        };
        assert_eq!(surface.degree_u(), 2);
        assert_eq!(surface.degree_v(), 2);
        assert_eq!(surface.control_point_count_u(), 9);
        assert_eq!(surface.control_point_count_v(), 5);
        assert_eq!(surface.domain_u(), 0.0..=std::f64::consts::TAU);
        assert_eq!(
            surface.domain_v(),
            -std::f64::consts::FRAC_PI_2..=std::f64::consts::FRAC_PI_2
        );
        assert_eq!(
            surface.control_point(0, 0).unwrap().point(),
            Point3::try_new(1.0, 2.0, 0.5).unwrap()
        );
        assert_eq!(
            surface.control_point(0, 1).unwrap().point(),
            Point3::try_new(3.5, 2.0, 0.5).unwrap()
        );
        assert_eq!(document.undo_label(), Some("Sphere"));

        registry.execute(&mut document, "Undo").unwrap();
        registry.execute(&mut document, "_Sph 1,2,3 1,5,3").unwrap();
        let Geometry::NurbsSurface(point_radius_surface) =
            document.objects().next().unwrap().geometry()
        else {
            panic!("Sph alias must create a NURBS surface")
        };
        let equator = point_radius_surface.evaluate(0.0, 0.0).unwrap();
        assert_eq!(equator, Point3::try_new(4.0, 2.0, 3.0).unwrap());

        for invalid in [
            "Sphere 0,0,0 0",
            "Sphere 0,0,0 -1",
            "Sphere 0,0,0 inf",
            "Sphere 0,0,0 1 2",
        ] {
            assert!(registry.execute(&mut document, invalid).is_err());
        }
        assert_eq!(document.objects().len(), 1);
        assert_eq!(document.undo_label(), Some("Sphere"));
    }

    #[test]
    fn ellipsoid_creates_exact_affine_sphere_from_radii_or_axis_points() {
        let registry = CommandRegistry::with_builtins();
        let mut document = Document::default();
        registry
            .execute(&mut document, "Ellipsoid 1,2,3 2 3 4")
            .unwrap();
        let ellipsoid_id = document.objects().next().unwrap().id();
        assert!(!document.is_selected(ellipsoid_id));
        let Geometry::NurbsSurface(surface) = document.object(ellipsoid_id).unwrap().geometry()
        else {
            panic!("Ellipsoid must create a NURBS surface")
        };
        assert_eq!(surface.degree_u(), 2);
        assert_eq!(surface.degree_v(), 2);
        assert_eq!(surface.control_point_count_u(), 9);
        assert_eq!(surface.control_point_count_v(), 5);
        assert_eq!(surface.domain_u(), 0.0..=std::f64::consts::TAU);
        assert_eq!(
            surface.domain_v(),
            -std::f64::consts::FRAC_PI_2..=std::f64::consts::FRAC_PI_2
        );
        assert_eq!(
            surface.evaluate(0.0, 0.0).unwrap(),
            Point3::try_new(3.0, 2.0, 3.0).unwrap()
        );
        assert_eq!(
            surface.evaluate(std::f64::consts::FRAC_PI_2, 0.0).unwrap(),
            Point3::try_new(1.0, 5.0, 3.0).unwrap()
        );
        assert_eq!(document.undo_label(), Some("Ellipsoid"));

        registry.execute(&mut document, "Undo").unwrap();
        registry
            .execute(&mut document, "Ellipsoid 1,2,3 1,4,3 -2,3,3 3,4,7")
            .unwrap();
        let Geometry::NurbsSurface(oriented) = document.objects().next().unwrap().geometry() else {
            panic!("Ellipsoid must support oriented axis points")
        };
        assert_eq!(
            oriented.evaluate(0.0, 0.0).unwrap(),
            Point3::try_new(1.0, 4.0, 3.0).unwrap()
        );
        assert_eq!(
            oriented.evaluate(std::f64::consts::FRAC_PI_2, 0.0).unwrap(),
            Point3::try_new(-2.0, 2.0, 3.0).unwrap()
        );
        assert_eq!(
            oriented.evaluate(0.0, std::f64::consts::FRAC_PI_2).unwrap(),
            Point3::try_new(1.0, 2.0, 7.0).unwrap()
        );

        for invalid in [
            "Ellipsoid 0,0,0 0 2 3",
            "Ellipsoid 0,0,0 1 -2 3",
            "Ellipsoid 0,0,0 1 2 inf",
            "Ellipsoid 0,0,0 1,0,0 2,0,0 0,0,3",
            "Ellipsoid 0,0,0 1,0,0 0,2,0 0,0,0",
            "Ellipsoid 0,0,0 1,0,0 0,2,0 1,1,0",
            "Ellipsoid 0,0,0 1 2",
            "Ellipsoid 0,0,0 1 2 3 4",
        ] {
            assert!(registry.execute(&mut document, invalid).is_err());
        }
        assert_eq!(document.objects().len(), 1);
        assert_eq!(document.undo_label(), Some("Ellipsoid"));
    }

    #[test]
    fn cylinder_creates_exact_signed_and_both_sides_surfaces() {
        let registry = CommandRegistry::with_builtins();
        let mut document = Document::default();
        registry
            .execute(&mut document, "Cylinder 1,2,3 2.5 -4 Solid=No")
            .unwrap();
        let cylinder_id = document.objects().next().unwrap().id();
        assert!(!document.is_selected(cylinder_id));
        let Geometry::NurbsSurface(surface) = document.object(cylinder_id).unwrap().geometry()
        else {
            panic!("Cylinder must create a NURBS surface")
        };
        assert_eq!(surface.degree_u(), 2);
        assert_eq!(surface.degree_v(), 1);
        assert_eq!(surface.control_point_count_u(), 9);
        assert_eq!(surface.control_point_count_v(), 2);
        assert_eq!(surface.domain_u(), 0.0..=std::f64::consts::TAU);
        assert_eq!(surface.domain_v(), -4.0..=0.0);
        assert_eq!(
            surface.control_point(0, 0).unwrap().point(),
            Point3::try_new(3.5, 2.0, -1.0).unwrap()
        );
        assert_eq!(document.undo_label(), Some("Cylinder"));

        registry.execute(&mut document, "Undo").unwrap();
        registry
            .execute(
                &mut document,
                "_Cyl 1,2,3 4,7,3 4 Axis=0,1,0 BothSides=Yes Solid=No",
            )
            .unwrap();
        let Geometry::NurbsSurface(both_sides) = document.objects().next().unwrap().geometry()
        else {
            panic!("Cyl alias must create a NURBS surface")
        };
        assert_eq!(both_sides.domain_v(), -4.0..=4.0);
        assert_eq!(
            both_sides.evaluate(0.0, -4.0).unwrap(),
            Point3::try_new(4.0, -2.0, 3.0).unwrap()
        );
        assert_eq!(
            both_sides.evaluate(0.0, 4.0).unwrap(),
            Point3::try_new(4.0, 6.0, 3.0).unwrap()
        );

        registry.execute(&mut document, "Undo").unwrap();
        let result = registry
            .execute(&mut document, "Cylinder 1,2,3 2.5 -4 Solid=Yes")
            .unwrap();
        assert!(result.contains("closed B-rep cylinder"));
        let Geometry::Brep(solid) = document.objects().next().unwrap().geometry() else {
            panic!("Cylinder Solid=Yes must create a B-rep")
        };
        assert_eq!(solid.faces().len(), 3);
        assert!(solid.is_solid());
        let mesh = solid.tessellate(8, document.tolerance()).unwrap();
        assert!(mesh.topology().is_solid());
        let expected_volume = std::f64::consts::PI * 2.5 * 2.5 * 4.0;
        assert!((mesh.signed_volume().unwrap() - expected_volume).abs() / expected_volume < 0.01);

        for invalid in [
            "Cylinder 0,0,0 1 0",
            "Cylinder 0,0,0 0 2",
            "Cylinder 0,0,0 0,0,2 3 Axis=0,0,1",
            "Cylinder 0,0,0 1 2 Axis=0,0,0",
            "Cylinder 0,0,0 1 2 BothSides=Maybe",
        ] {
            assert!(registry.execute(&mut document, invalid).is_err());
        }
        assert_eq!(document.objects().len(), 1);
        assert_eq!(document.undo_label(), Some("Cylinder"));
    }

    #[test]
    fn mesh_cylinder_matches_default_and_configurable_rhino_topology() {
        let registry = CommandRegistry::with_builtins();
        let mut document = Document::default();
        let parsed = parse_mesh_cylinder_options(&["0,0,0", "2", "5"]).unwrap();
        assert_eq!(parsed.vertical_count, 10);
        assert_eq!(parsed.around_count, 10);
        assert!(parsed.solid);
        assert_eq!(parsed.cap_style, MeshCapFaceStyle::Triangles);

        let message = registry
            .execute(&mut document, "MeshCylinder 0,0,0 2 5")
            .unwrap();
        assert!(message.ends_with("(10 around × 10 vertical faces)"));
        assert_eq!(document.selected_object_count(), 0);
        let Geometry::Mesh(default) = document.objects().next().unwrap().geometry() else {
            panic!("MeshCylinder must create a polygon mesh")
        };
        assert_eq!(default.vertices().len(), 132);
        assert_eq!(default.face_count(), 120);
        assert_eq!(
            default.faces()[0],
            viboceros_geometry::MeshFace::Quad([0, 1, 11, 10])
        );
        assert_eq!(
            default.faces()[100],
            viboceros_geometry::MeshFace::Triangle([110, 112, 111])
        );
        assert_eq!(
            default.faces()[110],
            viboceros_geometry::MeshFace::Triangle([121, 122, 123])
        );
        assert!(default.topology().is_solid());
        assert!(default.signed_volume().unwrap() > 0.0);
        assert_eq!(document.undo_label(), Some("MeshCylinder"));

        registry.execute(&mut document, "Undo").unwrap();
        registry
            .execute(
                &mut document,
                "MeshCylinder 1,2,3 2 -5 VerticalFaces=2 AroundFaces=6 CapFaceStyle=Quad",
            )
            .unwrap();
        let Geometry::Mesh(quads) = document.objects().next().unwrap().geometry() else {
            panic!("MeshCylinder quad-cap form must create a mesh")
        };
        assert_eq!(quads.vertices().len(), 32);
        assert_eq!(quads.face_count(), 18);
        assert_eq!(
            quads.faces()[12],
            viboceros_geometry::MeshFace::Quad([18, 21, 20, 19])
        );
        assert_eq!(
            quads.faces()[15],
            viboceros_geometry::MeshFace::Quad([25, 26, 27, 28])
        );
        assert_eq!(quads.bounds().min().z(), -2.0);
        assert_eq!(quads.bounds().max().z(), 3.0);
        assert!(quads.topology().is_solid());

        registry.execute(&mut document, "Undo").unwrap();
        registry
            .execute(
                &mut document,
                "MeshCylinder 0,0,0 0,2,0 4 Axis=1,0,0 BothSides=Yes Solid=No VerticalFaces=2 AroundFaces=4",
            )
            .unwrap();
        let Geometry::Mesh(open) = document.objects().next().unwrap().geometry() else {
            panic!("MeshCylinder open form must create a mesh")
        };
        assert_eq!(open.vertices().len(), 12);
        assert_eq!(open.face_count(), 8);
        assert_eq!(open.bounds().min().x(), -4.0);
        assert_eq!(open.bounds().max().x(), 4.0);
        assert!(!open.topology().is_closed());
    }

