        registry.execute(&mut document, "Undo").unwrap();
        registry
            .execute(
                &mut document,
                "MeshEllipsoid 1,2,3 1,6,3 1,4,6 3,4,5 VerticalFaces=4 AroundFaces=6 CapFaceStyle=Quad",
            )
            .unwrap();
