    #[test]
    fn extend_accepts_an_exact_domain_and_defaults_length_to_the_end() {
        let registry = CommandRegistry::with_builtins();
        let mut document = Document::default();
        registry.execute(&mut document, "Line 0,0 10,0").unwrap();
        let id = document.objects().next().unwrap().id();
        document.select_object(id, SelectionMode::Replace).unwrap();

        assert_eq!(
            registry
                .execute(&mut document, "Extend Domain=-5,15")
                .unwrap(),
            "Naturally extended the selected curve to include domain -5..15, merging the extension"
        );
        let Geometry::NurbsCurve(curve) = document.object(id).unwrap().geometry() else {
            panic!("Extend must create exact NURBS geometry")
        };
        assert_eq!(curve.domain(), -5.0..=15.0);
        assert!(curve.evaluate(-5.0).unwrap().is_near(
            Point3::try_new(-5.0, 0.0, 0.0).unwrap(),
            document.tolerance()
        ));
        assert!(curve.evaluate(15.0).unwrap().is_near(
            Point3::try_new(15.0, 0.0, 0.0).unwrap(),
            document.tolerance()
        ));

        document.select_object(id, SelectionMode::Replace).unwrap();
        assert_eq!(
            registry.execute(&mut document, "Extend Length=5").unwrap(),
            "Naturally extended the selected curve End by length 5, merging the extension"
        );
        let Geometry::NurbsCurve(curve) = document.object(id).unwrap().geometry() else {
            panic!("Extend must retain exact NURBS geometry")
        };
        assert_eq!(*curve.domain().start(), -5.0);
        assert!(document.tolerance().approx_eq(*curve.domain().end(), 20.0));
        assert!(curve.evaluate(*curve.domain().end()).unwrap().is_near(
            Point3::try_new(20.0, 0.0, 0.0).unwrap(),
            document.tolerance()
        ));
    }

    #[test]
    fn extend_rejects_invalid_requests_selection_and_closed_curves_atomically() {
        let registry = CommandRegistry::with_builtins();
        let mut document = Document::default();
        for command in [
            "Extend",
            "Extend Length",
            "Extend Domain=0",
            "Extend Domain=0,1 Side=End",
            "Extend Domain=0,1 Type=Arc",
            "Extend Domain=0,1 Type=Line",
            "Extend Domain=0,1 Join=No",
            "Extend Domain=0,1 Join=Yes",
            "Extend Length=1 Side=Middle",
            "Extend Length=1 Side=End Side=Start",
            "Extend Length=1 Type=Bezier",
            "Extend Length=1 Join=Maybe",
        ] {
            assert!(matches!(
                registry.execute(&mut document, command),
                Err(CommandError::Usage(EXTEND_CURVE_USAGE))
            ));
        }
        assert!(matches!(
            registry.execute(&mut document, "Extend Length=1"),
            Err(CommandError::ExtendRequiresOneCurve { actual: 0 })
        ));

        registry.execute(&mut document, "Circle 0,0 2").unwrap();
        let circle = document.objects().next().unwrap().id();
        document
            .select_object(circle, SelectionMode::Replace)
            .unwrap();
        let before = document.object(circle).unwrap().clone();
        assert!(matches!(
            registry.execute(&mut document, "Extend Length=1"),
            Err(CommandError::Geometry(
                GeometryError::CurveExtensionMustBeOpen
            ))
        ));
        assert_eq!(document.object(circle).unwrap(), &before);

        document.clear_selection();
        registry.execute(&mut document, "Line 0,0 1,0").unwrap();
        registry.execute(&mut document, "Line 0,1 1,1").unwrap();
        registry.execute(&mut document, "SelLine").unwrap();
        assert!(matches!(
            registry.execute(&mut document, "Extend Length=1"),
            Err(CommandError::ExtendRequiresOneCurve { actual: 2 })
        ));
        let line = document
            .objects()
            .find(|object| matches!(object.geometry(), Geometry::Line(_)))
            .unwrap()
            .id();
        document
            .select_object(line, SelectionMode::Replace)
            .unwrap();
        assert!(matches!(
            registry.execute(&mut document, "Extend Length=0"),
            Err(CommandError::Geometry(
                GeometryError::InvalidCurveExtensionLength
            ))
        ));
    }

    #[test]
    fn extend_surface_preserves_tensor_state_and_history() {
        let registry = CommandRegistry::with_builtins();
        let mut document = Document::default();
        registry
            .execute(&mut document, "Layer New SurfaceExtensions")
            .unwrap();
        registry
            .execute(&mut document, "SrfPt 0,0,0 3,0,1 3,4,4 0,4,2")
            .unwrap();
        let id = document.objects().next().unwrap().id();
        document.select_object(id, SelectionMode::Replace).unwrap();
        registry
            .execute(&mut document, "SetObjectName ExtendedPatch")
            .unwrap();
        registry
            .execute(&mut document, "Group SurfaceExtension")
            .unwrap();
        let before = document.object(id).unwrap().clone();
        let Geometry::NurbsSurface(source) = before.geometry() else {
            panic!("SrfPt must create a NURBS surface")
        };
        let expected = source.try_extended_u(-0.5..=2.0).unwrap();

        assert_eq!(
            registry
                .execute(
                    &mut document,
                    "ExtendSrf Direction=U Domain=-0.5,2 Type=Smooth Merge=Yes"
                )
                .unwrap(),
            "Smoothly extended the selected surface in U to include domain -0.5..2, merging the extension"
        );
        let object = document.object(id).unwrap();
        assert_eq!(object.geometry(), &Geometry::NurbsSurface(expected.clone()));
        assert_eq!(object.attributes(), before.attributes());
        assert!(document.is_selected(id));
        assert!(
            document
                .group_by_name("SurfaceExtension")
                .unwrap()
                .members()
                .any(|member| member == id)
        );
        assert_eq!(document.undo_label(), Some("ExtendSrf"));

        registry.execute(&mut document, "Undo").unwrap();
        assert_eq!(document.object(id).unwrap(), &before);
        registry.execute(&mut document, "Redo").unwrap();
        assert_eq!(
            document.object(id).unwrap().geometry(),
            &Geometry::NurbsSurface(expected)
        );
    }

    #[test]
    fn extend_surface_accepts_a_rhino_compatible_edge_distance() {
        let registry = CommandRegistry::with_builtins();
        let mut document = Document::default();
        registry
            .execute(&mut document, "SrfPt 0,0,0 10,0,0 20,10,0 0,10,0")
            .unwrap();
        let id = document.objects().next().unwrap().id();
        document.select_object(id, SelectionMode::Replace).unwrap();
        let Geometry::NurbsSurface(source) = document.object(id).unwrap().geometry() else {
            panic!("SrfPt must create a NURBS surface")
        };
        let expected = source
            .try_extended_by_length(SurfaceExtensionEdge::East, 3.0)
            .unwrap();
        let expected_line = source
            .try_extended_linearly_by_length(SurfaceExtensionEdge::East, 3.0)
            .unwrap();
        let expected_shrink = source
            .try_shrunk_by_length(SurfaceExtensionEdge::East, 2.0, None, document.tolerance())
            .unwrap();
        let expected_shrink_at = source
            .try_shrunk_by_length(
                SurfaceExtensionEdge::East,
                2.0,
                Some(0.0),
                document.tolerance(),
            )
            .unwrap();

        assert_eq!(
            registry
                .execute(
                    &mut document,
                    "ExtendSrf Edge=East Distance=3 Type=Smooth Merge=Yes"
                )
                .unwrap(),
            "Smoothly extended the selected surface at its East edge by distance 3, merging the extension"
        );
        assert_eq!(
            document.object(id).unwrap().geometry(),
            &Geometry::NurbsSurface(expected)
        );
        assert_eq!(document.undo_label(), Some("ExtendSrf"));

        registry.execute(&mut document, "Undo").unwrap();
        assert_eq!(
            registry
                .execute(
                    &mut document,
                    "ExtendSrf Edge=East Distance=3 Type=Line Merge=Yes"
                )
                .unwrap(),
            "Linearly extended the selected surface at its East edge by distance 3, merging the extension"
        );
        assert_eq!(
            document.object(id).unwrap().geometry(),
            &Geometry::NurbsSurface(expected_line)
        );

        registry.execute(&mut document, "Undo").unwrap();
        assert_eq!(
            registry
                .execute(&mut document, "ExtendSrf Edge=East Distance=-2 Type=Line")
                .unwrap(),
            "Shrank the selected surface at its East edge inward by distance 2"
        );
        assert_eq!(
            document.object(id).unwrap().geometry(),
            &Geometry::NurbsSurface(expected_shrink)
        );

        registry.execute(&mut document, "Undo").unwrap();
        assert_eq!(
            registry
                .execute(&mut document, "ExtendSrf Edge=East Distance=-2 At=0")
                .unwrap(),
            "Shrank the selected surface at its East edge inward by distance 2"
        );
        assert_eq!(
            document.object(id).unwrap().geometry(),
            &Geometry::NurbsSurface(expected_shrink_at)
        );
    }

    #[test]
    fn extend_surface_point_pick_resolves_the_natural_edge_and_shrink_path() {
        let registry = CommandRegistry::with_builtins();
        let mut document = Document::default();
        registry
            .execute(&mut document, "SrfPt 0,0,0 10,0,0 20,10,0 0,10,0")
            .unwrap();
        let id = document.objects().next().unwrap().id();
        document.select_object(id, SelectionMode::Replace).unwrap();
        let Geometry::NurbsSurface(source) = document.object(id).unwrap().geometry() else {
            panic!("SrfPt must create a NURBS surface")
        };
        let source = source.clone();
        let u = source.parameter_at_u(0.37).unwrap();
        let v = source.parameter_at_v(0.25).unwrap();
        let domain_u = source.domain_u();
        let domain_v = source.domain_v();
        for (expected_edge, expected_parameter, pick) in [
            (
                SurfaceExtensionEdge::South,
                u,
                source.evaluate(u, *domain_v.start()).unwrap(),
            ),
            (
                SurfaceExtensionEdge::East,
                v,
                source.evaluate(*domain_u.end(), v).unwrap(),
            ),
            (
                SurfaceExtensionEdge::North,
                u,
                source.evaluate(u, *domain_v.end()).unwrap(),
            ),
            (
                SurfaceExtensionEdge::West,
                v,
                source.evaluate(*domain_u.start(), v).unwrap(),
            ),
        ] {
            let (edge, parameter) =
                closest_surface_extension_edge(&source, pick, document.tolerance()).unwrap();
            assert_eq!(edge, expected_edge);
            assert!(
                document
                    .tolerance()
                    .approx_eq(parameter, expected_parameter)
            );
        }

        let east_pick = source.evaluate(*domain_u.end(), v).unwrap();
        let expected_shrink = source
            .try_shrunk_by_length(
                SurfaceExtensionEdge::East,
                2.0,
                Some(v),
                document.tolerance(),
            )
            .unwrap();
        assert_eq!(
            registry
                .execute(
                    &mut document,
                    &format!(
                        "ExtendSrf {:.17},{:.17},{:.17} Distance=-2 Type=Line Merge=Yes",
                        east_pick.x(),
                        east_pick.y(),
                        east_pick.z()
                    ),
                )
                .unwrap(),
            "Shrank the selected surface at its East edge inward by distance 2"
        );
        assert_eq!(
            document.object(id).unwrap().geometry(),
            &Geometry::NurbsSurface(expected_shrink)
        );

        registry.execute(&mut document, "Undo").unwrap();
        let south_pick = source.evaluate(u, *domain_v.start()).unwrap();
        let expected_extension = source
            .try_extended_linearly_by_length(SurfaceExtensionEdge::South, 2.0)
            .unwrap();
        registry
            .execute(
                &mut document,
                &format!(
                    "ExtendSrf {:.17},{:.17},{:.17} Distance=2 Type=Line Merge=Yes",
                    south_pick.x(),
                    south_pick.y(),
                    south_pick.z()
                ),
            )
            .unwrap();
        assert_eq!(
            document.object(id).unwrap().geometry(),
            &Geometry::NurbsSurface(expected_extension)
        );
    }

    #[test]
